import React, { useState } from 'react';

interface NavbarProps {
  onNavigate: (page: string) => void;
  currentPage: string;
}

const Navbar: React.FC<NavbarProps> = ({ onNavigate, currentPage }) => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const toggleMenu = () => setIsMenuOpen(!isMenuOpen);

  const handleLinkClick = (page: string) => {
    onNavigate(page);
    setIsMenuOpen(false);
  };

  return (
    <header className="bg-[#cab89d] border-b border-[#D6C7B2] py-4 md:py-6 sticky top-0 z-50">
      <div className="max-w-[1440px] mx-auto px-6 md:px-20 flex justify-between items-center">
        <div 
          className="text-xl md:text-2xl font-normal text-[#4B3827] tracking-tight cursor-pointer hover:opacity-80 transition-opacity"
          onClick={() => handleLinkClick('home')}
        >
          Kashmiri Visual Arts
        </div>

        {/* Desktop Nav */}
        <nav className="hidden md:flex items-center gap-0">
          <button 
            onClick={() => handleLinkClick('home')}
            className={`px-3 text-[17px] transition-colors ${currentPage === 'home' ? 'text-[#4B3827] font-semibold underline decoration-1 underline-offset-4' : 'text-[#5A4632] hover:text-[#3F2E1E]'}`}
          >
            Art Forms
          </button>
          <span className="text-[#8A7660] text-sm px-1">|</span>
          <button 
            onClick={() => handleLinkClick('explore')}
            className={`px-3 text-[17px] transition-colors ${currentPage === 'explore' ? 'text-[#4B3827] font-semibold underline decoration-1 underline-offset-4' : 'text-[#5A4632] hover:text-[#3F2E1E]'}`}
          >
            Explore
          </button>
          <span className="text-[#8A7660] text-sm px-1">|</span>
          <button className="px-3 text-[17px] text-[#5A4632] hover:text-[#3F2E1E] transition-colors">Artists</button>
          <span className="text-[#8A7660] text-sm px-1">|</span>
          <button className="px-3 text-[17px] text-[#5A4632] hover:text-[#3F2E1E] transition-colors">About</button>
        </nav>

        {/* Mobile Toggle */}
        <button 
          onClick={toggleMenu}
          className="md:hidden p-2 text-[#4B3827]"
          aria-label="Toggle Menu"
        >
          {isMenuOpen ? (
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          ) : (
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16m-7 6h7" />
            </svg>
          )}
        </button>
      </div>

      {/* Mobile Menu */}
      {isMenuOpen && (
        <div className="md:hidden absolute top-full left-0 w-full bg-[#cab89d] border-b border-[#D6C7B2] py-4 px-6 flex flex-col gap-4 shadow-xl">
          <button onClick={() => handleLinkClick('home')} className="text-left py-2 text-lg text-[#4B3827]">Art Forms</button>
          <button onClick={() => handleLinkClick('explore')} className="text-left py-2 text-lg text-[#4B3827]">Explore Archive</button>
          <button className="text-left py-2 text-lg text-[#4B3827]">Featured Artists</button>
          <button className="text-left py-2 text-lg text-[#4B3827]">About Project</button>
        </div>
      )}
    </header>
  );
};

export default Navbar;

