import React, { useState, useEffect, useRef } from 'react';
import Hero from '../components/Hero';
import { ARTISANS } from '../constants'; 
import { ArtForm } from '../types';

interface ArtFormDetailPageProps {
  artForm: ArtForm;
  onBack: () => void;
}

const ArtFormDetailPage: React.FC<ArtFormDetailPageProps> = ({ artForm, onBack }) => {
  const [displayText, setDisplayText] = useState('');
  const [isExpanded, setIsExpanded] = useState(false);
  const typingRef = useRef<any>(null);

  const truncatedText = artForm.fullDescription.slice(0, 150) + "...";
  const fullText = artForm.fullDescription;

  useEffect(() => {
    setDisplayText(truncatedText);
    return () => {
      if (typingRef.current) clearTimeout(typingRef.current);
    };
  }, [artForm, truncatedText]);

  const handleToggle = () => {
    if (!isExpanded) {
      // Start typing effect
      let currentText = truncatedText;
      let charIndex = 150;

      const type = () => {
        if (charIndex < fullText.length) {
          currentText += fullText[charIndex];
          setDisplayText(currentText);
          charIndex++;
          typingRef.current = setTimeout(type, 15);
        } else {
          setIsExpanded(true);
        }
      };
      type();
    } else {
      setDisplayText(truncatedText);
      setIsExpanded(false);
      if (typingRef.current) clearTimeout(typingRef.current);
    }
  };

  if (!artForm) return null;

  return (
    <div className="bg-[#cab89d] min-h-screen">
      <Hero 
        title={artForm.name}
        subtitle={`The traditional Kashmiri ${artForm.name} craft.`}
        image={artForm.image}
        compact
      />

      <main className="max-w-[1300px] mx-auto px-4 md:px-6 py-12 md:py-16">
        {/* About Section */}
        <section className="flex flex-col lg:flex-row gap-8 md:gap-12 mb-16 md:mb-20">
          <div className="flex-1 order-2 lg:order-1">
            <h2 className="text-3xl md:text-4xl font-playfair text-[#7b4f3a] mb-6">About {artForm.name}</h2>
            <div className="relative font-lora text-base md:text-lg leading-relaxed text-[#4B3827]">
              <p className="mb-4">{displayText}</p>
              <button 
                onClick={handleToggle}
                className="text-[#7b4f3a] font-bold hover:underline transition-all flex items-center gap-2 mt-4 text-sm md:text-base"
              >
                {isExpanded ? 'Read Less ▲' : 'Read More >>>'}
              </button>
            </div>
          </div>
          <div className="flex-1 order-1 lg:order-2">
            <img 
              src={artForm.image} 
              alt={artForm.name} 
              className="w-full h-[300px] md:h-[400px] object-cover border-4 md:border-[10px] border-white/20 shadow-xl rounded-sm"
            />
          </div>
        </section>

        {/* Process Section */}
        {artForm.process && (
          <section className="mb-16 md:mb-20">
            <h2 className="text-2xl md:text-3xl font-playfair text-[#7b4f3a] mb-8 md:mb-10 tracking-widest uppercase border-l-4 border-[#7b4f3a] pl-4">The Process</h2>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
              {artForm.process.map((step: any, idx: number) => (
                <div key={idx} className="bg-white/80 p-3 shadow-sm group md:hover:shadow-lg transition-shadow rounded-sm">
                  <div className="overflow-hidden mb-4 rounded-sm h-40">
                    <img src={step.image} alt={step.title} className="w-full h-full object-cover md:group-hover:scale-105 transition-transform duration-500" />
                  </div>
                  <h3 className="text-lg font-bold text-[#3E2D1F] mb-1 font-playfair">{step.title}</h3>
                  <p className="text-sm text-[#7a6041] font-lora italic">{step.description}</p>
                </div>
              ))}
            </div>
          </section>
        )}

        {/* Products Section */}
        {artForm.products && (
          <section className="mb-16 md:mb-20">
            <h2 className="text-2xl md:text-3xl font-playfair text-[#7b4f3a] mb-8 md:mb-10 tracking-widest uppercase border-l-4 border-[#7b4f3a] pl-4">Creations</h2>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
              {artForm.products.map((product: any, idx: number) => (
                <div key={idx} className="bg-white/90 p-3 shadow-md rounded-sm">
                  <div className="h-48 md:h-52 overflow-hidden rounded-sm mb-4">
                    <img src={product.image} alt={product.name} className="w-full h-full object-cover" />
                  </div>
                  <h4 className="text-md font-semibold text-[#3E2D1F] mb-3 font-playfair">{product.name}</h4>
                  <button className="w-full py-2.5 border border-black/10 text-[#7b4f3a] hover:bg-[#7b4f3a] hover:text-white transition-colors uppercase text-[10px] md:text-xs tracking-widest font-bold">
                    Catalog Inquiry
                  </button>
                </div>
              ))}
            </div>
          </section>
        )}

        {/* Artisans Section */}
        <section className="mb-10">
          <h2 className="text-2xl md:text-3xl font-playfair text-[#7b4f3a] mb-8 md:mb-10 tracking-widest uppercase border-l-4 border-[#7b4f3a] pl-4">Masters of the Craft</h2>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 md:gap-6">
            {ARTISANS.slice(0, 4).map((artisan: any, idx: number) => (
              <div key={idx} className="bg-white/60 p-4 shadow-sm text-center rounded-sm">
                <div className="w-20 h-20 md:w-32 md:h-32 rounded-full mx-auto overflow-hidden mb-4 border-2 border-[#D6C7B2]">
                  <img src={artisan.image} alt={artisan.name} className="w-full h-full object-cover grayscale md:hover:grayscale-0 transition-all duration-500" />
                </div>
                <h5 className="text-base md:text-lg font-bold text-[#3E2D1F] mb-1 font-playfair">{artisan.name}</h5>
                <p className="text-[10px] md:text-xs text-[#7a6041] uppercase tracking-wider font-bold">{artisan.experience}</p>
              </div>
            ))}
          </div>
        </section>

        <div className="text-center mt-12 md:mt-20">
          <button 
            onClick={onBack}
            className="text-[#7b4f3a] font-bold border-b-2 border-[#7b4f3a] pb-1 hover:text-[#3E2D1F] hover:border-[#3E2D1F] transition-all font-lora tracking-widest uppercase text-sm"
          >
            ← Back to All Art Forms
          </button>
        </div>
      </main>
    </div>
  );
};

