import React, { useState } from 'react';
import { User, Artisan } from '../types';

interface DashboardPageProps {
  user: User;
  artisans: Artisan[];
  onUpdateArtisans: (list: Artisan[]) => void;
}

const DashboardPage: React.FC<DashboardPageProps> = ({ user, artisans, onUpdateArtisans }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'review' | 'edit'>('overview');
  const [successMsg, setSuccessMsg] = useState('');

  // Find target artisan if role is artisan
  const myProfile = artisans.find(a => a.id === user.artisanId);

  // Pending tasks for admin
  const pendingRequests = artisans.filter(a => a.status === 'pending' || a.pendingChanges);

  const handleApplyChanges = (artisanId: string) => {
    const newList = artisans.map(a => {
      if (a.id === artisanId) {
        if (a.status === 'pending') return { ...a, status: 'live' as const };
        if (a.pendingChanges) {
          const updated = { ...a, ...a.pendingChanges, pendingChanges: undefined };
          return updated as Artisan;
        }
      }
      return a;
    });
    onUpdateArtisans(newList);
    setSuccessMsg('Changes approved and merged into live archive.');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const handleRejectChanges = (artisanId: string) => {
    const newList = artisans.map(a => {
      if (a.id === artisanId) {
        return { ...a, pendingChanges: undefined };
      }
      return a;
    });
    onUpdateArtisans(newList);
  };

  const handleArtisanSubmitEdits = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const edits = {
      bio: formData.get('bio') as string,
      location: formData.get('location') as string,
    };

    const newList = artisans.map(a => {
      if (a.id === user.artisanId) {
        return { ...a, pendingChanges: edits };
      }
      return a;
    });
    onUpdateArtisans(newList);
    setSuccessMsg('Profile updates submitted for admin review.');
    setActiveTab('overview');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  return (
    <div className="bg-[#cab89d] min-h-screen py-10 px-4 md:px-20 max-w-[1440px] mx-auto">
      {/* Dashboard Header */}
      <div className="flex flex-col md:flex-row justify-between items-end mb-10 border-b border-[#D6C7B2] pb-8 gap-6">
        <div>
          <h1 className="text-4xl md:text-5xl font-playfair text-[#3E2D1F] mb-2 uppercase tracking-tight">
            {user.role === 'admin' ? 'Admin Control Center' : 'Artisan Workspace'}
          </h1>
          <p className="font-lora italic text-[#5A4632]">
            Welcome back, <span className="font-bold text-[#4B3827]">{user.name}</span>. Accessing archive as <span className="uppercase text-xs font-bold px-2 py-0.5 bg-[#4B3827] text-white rounded-full">{user.role}</span>
          </p>
        </div>

        <div className="flex gap-2">
           <button 
             onClick={() => setActiveTab('overview')}
             className={`px-6 py-2 text-xs font-bold uppercase tracking-widest border-b-2 transition-all ${activeTab === 'overview' ? 'border-[#7B4A2E] text-[#7B4A2E]' : 'border-transparent text-[#8A7660] hover:text-[#4B3827]'}`}
           >
             Overview
           </button>
           {user.role === 'admin' ? (
              <button 
                onClick={() => setActiveTab('review')}
                className={`relative px-6 py-2 text-xs font-bold uppercase tracking-widest border-b-2 transition-all ${activeTab === 'review' ? 'border-[#7B4A2E] text-[#7B4A2E]' : 'border-transparent text-[#8A7660] hover:text-[#4B3827]'}`}
              >
                Pending Review
                {pendingRequests.length > 0 && (
                  <span className="absolute -top-1 -right-1 w-4 h-4 bg-[#7B4A2E] text-white text-[10px] flex items-center justify-center rounded-full animate-bounce">
                    {pendingRequests.length}
                  </span>
                )}
              </button>
           ) : (
              <button 
                onClick={() => setActiveTab('edit')}
                className={`px-6 py-2 text-xs font-bold uppercase tracking-widest border-b-2 transition-all ${activeTab === 'edit' ? 'border-[#7B4A2E] text-[#7B4A2E]' : 'border-transparent text-[#8A7660] hover:text-[#4B3827]'}`}
              >
                Edit My Profile
              </button>
           )}
        </div>
      </div>

      {successMsg && (
        <div className="mb-8 p-4 bg-green-100 border border-green-200 text-green-800 text-sm font-bold flex items-center gap-3 rounded-sm animate-fade-in">
           <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg>
           {successMsg}
        </div>
      )}

      {/* --- ADMIN VIEW: REVIEW --- */}
      {user.role === 'admin' && activeTab === 'review' && (
        <section className="space-y-8 animate-fade-in">
           <h2 className="text-2xl font-playfair text-[#3E2D1F] border-l-4 border-[#7B4A2E] pl-4 mb-6">Archive Task Queue</h2>
           {pendingRequests.length > 0 ? (
             <div className="grid grid-cols-1 gap-6">
                {pendingRequests.map(artisan => (
                  <div key={artisan.id} className="bg-white/80 p-8 border border-[#D6C7B2] shadow-sm flex flex-col md:flex-row gap-8 items-start">
                    <img src={artisan.image} className="w-24 h-24 object-cover rounded-full shadow-md" alt="" />
                    <div className="flex-grow">
                      <div className="flex items-center gap-3 mb-2">
                        <h3 className="text-xl font-bold font-playfair">{artisan.name}</h3>
                        <span className="text-[10px] bg-[#7B4A2E] text-white px-2 py-0.5 font-bold uppercase tracking-widest">
                          {artisan.pendingChanges ? 'Edit Request' : 'New Registration'}
                        </span>
                      </div>
                      <p className="text-sm text-[#5A4632] mb-4">Master of <span className="font-bold underline">{artisan.role}</span></p>

                      {artisan.pendingChanges && (
                        <div className="bg-[#F2E6D8] p-4 rounded-sm border border-[#D6C7B2] mb-6">
                           <p className="text-xs font-bold uppercase text-[#8A7660] mb-2">Changes for Approval:</p>
                           <ul className="text-sm space-y-2">
                              {Object.entries(artisan.pendingChanges).map(([key, val]) => (
                                <li key={key} className="flex gap-2">
                                  <span className="font-bold capitalize">{key}:</span>
                                  <span className="italic">{val}</span>
                                </li>
                              ))}
                           </ul>
                        </div>
                      )}

                      <div className="flex gap-4">
                        <button 
                          onClick={() => handleApplyChanges(artisan.id)}
                          className="bg-[#3E2D1F] text-[#F5F1EA] px-8 py-2 text-xs font-bold uppercase tracking-widest hover:bg-black transition-all"
                        >
                          Approve & Go Live
                        </button>
                        <button 
                          onClick={() => handleRejectChanges(artisan.id)}
                          className="border border-[#7B4A2E] text-[#7B4A2E] px-8 py-2 text-xs font-bold uppercase tracking-widest hover:bg-[#7B4A2E] hover:text-white transition-all"
                        >
                          Reject Changes
                        </button>
                      </div>
                    </div>
                  </div>
                ))}
             </div>
           ) : (
             <div className="py-20 text-center border-2 border-dashed border-[#D6C7B2]">
                <p className="font-lora italic text-[#8A7660]">The moderation queue is currently empty. All data is verified.</p>
             </div>
           )}
        </section>
      )}

      {/* --- ARTISAN VIEW: EDIT --- */}
      {user.role === 'artisan' && activeTab === 'edit' && myProfile && (
        <section className="animate-fade-in max-w-3xl">
          <h2 className="text-2xl font-playfair text-[#3E2D1F] border-l-4 border-[#7B4A2E] pl-4 mb-8">Maintain My Archive Profile</h2>

          <form onSubmit={handleArtisanSubmitEdits} className="space-y-8 bg-white/40 p-10 border border-[#D6C7B2]">
             <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-[10px] font-bold uppercase tracking-widest text-[#8A7660] mb-2">Work Location</label>
                  <input 
                    name="location"
                    defaultValue={myProfile.location}
                    className="w-full bg-[#cab89d]/20 border border-[#D6C7B2] p-3 font-lora text-sm focus:outline-none focus:ring-1 focus:ring-[#7B4A2E]" 
                  />
                </div>
                <div>
                   <label className="block text-[10px] font-bold uppercase tracking-widest text-[#8A7660] mb-2">Update Profile Picture</label>
                   <input type="file" className="text-xs text-[#5A4632]" />
                </div>
             </div>

             <div>
                <label className="block text-[10px] font-bold uppercase tracking-widest text-[#8A7660] mb-2">My Bio / Artistic Statement</label>
                <textarea 
                  name="bio"
                  defaultValue={myProfile.bio}
                  rows={4}
                  className="w-full bg-[#cab89d]/20 border border-[#D6C7B2] p-3 font-lora text-sm focus:outline-none focus:ring-1 focus:ring-[#7B4A2E]" 
                />
             </div>

             <div className="border-t border-[#D6C7B2] pt-8">
                <h3 className="text-lg font-playfair mb-4">Media Proof Vault</h3>
                <p className="text-xs text-[#8A7660] mb-4">Upload high-resolution images of your workshop, certificates, or exhibition proofs.</p>
                <div className="w-full h-32 border-2 border-dashed border-[#D6C7B2] flex items-center justify-center hover:bg-[#D6C7B2]/20 cursor-pointer transition-all">
                   <span className="text-xs uppercase font-bold text-[#4B3827] tracking-widest">Click to upload media files</span>
                </div>
             </div>

             <div className="pt-6">
                <button 
                  type="submit"
                  className="bg-[#3E2D1F] text-[#F5F1EA] px-12 py-4 text-xs font-bold uppercase tracking-widest hover:shadow-xl transition-all shadow-md active:scale-95"
                >
                  Submit Changes for Review
                </button>
                <p className="mt-4 text-[10px] text-[#8A7660] italic">
                  Note: Changes will be hidden from the public archive until verified by the board administrator.
                </p>
             </div>
          </form>
        </section>
      )}

      {/* --- OVERVIEW TAB (Both Roles) --- */}
      {activeTab === 'overview' && (
        <section className="grid grid-cols-1 lg:grid-cols-3 gap-10 animate-fade-in">
           {/* Stats Cards */}
           <div className="lg:col-span-2 space-y-8">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                 <div className="bg-white/90 p-6 shadow-sm border border-[#D6C7B2]">
                    <span className="text-[10px] uppercase font-bold tracking-widest text-[#8A7660]">Registered Artists</span>
                    <p className="text-4xl font-playfair mt-2">{artisans.length}</p>
                 </div>
                 <div className="bg-white/90 p-6 shadow-sm border border-[#D6C7B2]">
                    <span className="text-[10px] uppercase font-bold tracking-widest text-[#8A7660]">Verified Traditions</span>
                    <p className="text-4xl font-playfair mt-2">{ART_FORMS.length}</p>
                 </div>
                 <div className="bg-white/90 p-6 shadow-sm border border-[#D6C7B2]">
                    <span className="text-[10px] uppercase font-bold tracking-widest text-[#8A7660]">Active Moderation</span>
