import React, { useState } from 'react';
import { User, Artisan } from '../types';
// Fixed: Added missing import for ART_FORMS
import { ART_FORMS } from '../constants';

interface DashboardPageProps {
  user: User;
  artisans: Artisan[];
  onUpdateArtisans: (list: Artisan[]) => void;
}

const DashboardPage: React.FC<DashboardPageProps> = ({ user, artisans, onUpdateArtisans }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'review' | 'edit'>('overview');
  const [successMsg, setSuccessMsg] = useState('');

  // Find target artisan if role is artisan
  const myProfile = artisans.find(a => a.id === user.artisanId);

  // Pending tasks for admin
  const pendingRequests = artisans.filter(a => a.status === 'pending' || a.pendingChanges);

  const handleApplyChanges = (artisanId: string) => {
    const newList = artisans.map(a => {
      if (a.id === artisanId) {
        if (a.status === 'pending') return { ...a, status: 'live' as const };
        if (a.pendingChanges) {
          const updated = { ...a, ...a.pendingChanges, pendingChanges: undefined };
          return updated as Artisan;
        }
      }
      return a;
    });
    onUpdateArtisans(newList);
    setSuccessMsg('Changes approved and merged into live archive.');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const handleRejectChanges = (artisanId: string) => {
    const newList = artisans.map(a => {
      if (a.id === artisanId) {
        return { ...a, pendingChanges: undefined };
      }
      return a;
    });
    onUpdateArtisans(newList);
  };

  const handleArtisanSubmitEdits = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const edits = {
      bio: formData.get('bio') as string,
      location: formData.get('location') as string,
    };

    const newList = artisans.map(a => {
      if (a.id === user.artisanId) {
        return { ...a, pendingChanges: edits };
      }
      return a;
    });
    onUpdateArtisans(newList);
    setSuccessMsg('Profile updates submitted for admin review.');
    setActiveTab('overview');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  return (
    <div className="bg-[#cab89d] min-h-screen py-10 px-4 md:px-20 max-w-[1440px] mx-auto">
      {/* Dashboard Header */}
      <div className="flex flex-col md:flex-row justify-between items-end mb-10 border-b border-[#D6C7B2] pb-8 gap-6">
        <div>
          <h1 className="text-4xl md:text-5xl font-playfair text-[#3E2D1F] mb-2 uppercase tracking-tight">
            {user.role === 'admin' ? 'Admin Control Center' : 'Artisan Workspace'}
          </h1>
          <p className="font-lora italic text-[#5A4632]">
            Welcome back, <span className="font-bold text-[#4B3827]">{user.name}</span>. Accessing archive as <span className="uppercase text-xs font-bold px-2 py-0.5 bg-[#4B3827] text-white rounded-full">{user.role}</span>
          </p>
        </div>

        <div className="flex gap-2">
           <button 
             onClick={() => setActiveTab('overview')}
             className={`px-6 py-2 text-xs font-bold uppercase tracking-widest border-b-2 transition-all ${activeTab === 'overview' ? 'border-[#7B4A2E] text-[#7B4A2E]' : 'border-transparent text-[#8A7660] hover:text-[#4B3827]'}`}
           >
             Overview
           </button>
           {user.role === 'admin' ? (
              <button 
                onClick={() => setActiveTab('review')}
                className={`relative px-6 py-2 text-xs font-bold uppercase tracking-widest border-b-2 transition-all ${activeTab === 'review' ? 'border-[#7B4A2E] text-[#7B4A2E]' : 'border-transparent text-[#8A7660] hover:text-[#4B3827]'}`}
              >
                Pending Review
                {pendingRequests.length > 0 && (
                  <span className="absolute -top-1 -right-1 w-4 h-4 bg-[#7B4A2E] text-white text-[10px] flex items-center justify-center rounded-full animate-bounce">
                    {pendingRequests.length}
                  </span>
                )}
              </button>
           ) : (
              <button 
                onClick={() => setActiveTab('edit')}
                className={`px-6 py-2 text-xs font-bold uppercase tracking-widest border-b-2 transition-all ${activeTab === 'edit' ? 'border-[#7B4A2E] text-[#7B4A2E]' : 'border-transparent text-[#8A7660] hover:text-[#4B3827]'}`}
              >
                Edit My Profile
              </button>
           )}
        </div>
      </div>

      {successMsg && (
        <div className="mb-8 p-4 bg-green-100 border border-green-200 text-green-800 text-sm font-bold flex items-center gap-3 rounded-sm animate-fade-in">
           <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg>
           {successMsg}
        </div>
      )}

      {/* --- ADMIN VIEW: REVIEW --- */}
      {user.role === 'admin' && activeTab === 'review' && (
        <section className="space-y-8 animate-fade-in">
           <h2 className="text-2xl font-playfair text-[#3E2D1F] border-l-4 border-[#7B4A2E] pl-4 mb-6">Archive Task Queue</h2>
           {pendingRequests.length > 0 ? (
             <div className="grid grid-cols-1 gap-6">
                {pendingRequests.map(artisan => (
                  <div key={artisan.id} className="bg-white/80 p-8 border border-[#D6C7B2] shadow-sm flex flex-col md:flex-row gap-8 items-start">
