                                </li>
                              ))}
                           </ul>
                        </div>
                      )}

                      <div className="flex gap-4">
                        <button 
                          onClick={() => handleApplyChanges(artisan.id)}
                          className="bg-[#3E2D1F] text-[#F5F1EA] px-8 py-2 text-xs font-bold uppercase tracking-widest hover:bg-black transition-all"
