export type Role = 'admin' | 'artisan' | 'guest';

export interface User {
  id: string;
  name: string;
  role: Role;
  artisanId?: string; // Links user to their artisan profile if role is 'artisan'
}

export interface ArtForm {
  id: string;
  name: string;
  shortDescription: string;
  fullDescription: string;
  image: string;
  process?: ProcessStep[];
  products?: Product[];
}

export interface ProcessStep {
  title: string;
  description: string;
  image: string;
}

export interface Product {
  name: string;
  image: string;
}

export interface MediaProof {
  id: string;
  title: string;
  type: 'image' | 'document';
  url: string;
  status: 'pending' | 'approved' | 'rejected';
}

export interface Artwork {
  id: string;
  title: string;
  description: string;
  price: string;
  image: string;
  status: 'pending' | 'live' | 'rejected';
}

export interface Artisan {
  id: string;
  name: string;
  role: string;
  experience: string;
  experienceYears: number;
  age: number;
  location: string;
  artworksCount: number;
  bio: string;
  image: string;
  specialties?: string[];
  status: 'live' | 'pending' | 'suspended';
  mediaProof?: MediaProof[];
  pendingChanges?: Partial<Artisan>; // Stores edits waiting for admin approval
  artworks: Artwork[];
}

import React, { useState } from 'react';
import { User, Artisan, Artwork } from '../types';
import { ART_FORMS } from '../constants';

interface DashboardPageProps {
  user: User;
  artisans: Artisan[];
  onUpdateArtisans: (list: Artisan[]) => void;
}

const DashboardPage: React.FC<DashboardPageProps> = ({ user, artisans, onUpdateArtisans }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'review' | 'edit' | 'artworks'>('overview');
  const [successMsg, setSuccessMsg] = useState('');

  // Find target artisan if role is artisan
  const myProfile = artisans.find(a => a.id === user.artisanId);

  // Pending tasks for admin: either profile level pending, or any artwork pending
  const pendingRequests = artisans.filter(a => 
    a.status === 'pending' || 
    a.pendingChanges || 
    a.artworks.some(aw => aw.status === 'pending')
  );

  const handleApproveProfile = (artisanId: string) => {
    const newList = artisans.map(a => {
      if (a.id === artisanId) {
        if (a.status === 'pending') return { ...a, status: 'live' as const };
        if (a.pendingChanges) {
          const updated = { ...a, ...a.pendingChanges, pendingChanges: undefined };
          return updated as Artisan;
        }
      }
      return a;
    });
    onUpdateArtisans(newList);
    setSuccessMsg('Profile changes approved.');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const handleApproveArtwork = (artisanId: string, artworkId: string) => {
    const newList = artisans.map(a => {
      if (a.id === artisanId) {
        return {
          ...a,
          artworks: a.artworks.map(aw => aw.id === artworkId ? { ...aw, status: 'live' as const } : aw)
        };
      }
      return a;
    });
    onUpdateArtisans(newList);
    setSuccessMsg('Artwork approved and added to live gallery.');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const handleRejectArtwork = (artisanId: string, artworkId: string) => {
    const newList = artisans.map(a => {
      if (a.id === artisanId) {
        return {
          ...a,
          artworks: a.artworks.map(aw => aw.id === artworkId ? { ...aw, status: 'rejected' as const } : aw)
        };
      }
      return a;
    });
    onUpdateArtisans(newList);
  };

  const handleArtisanSubmitEdits = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const edits = {
      bio: formData.get('bio') as string,
      location: formData.get('location') as string,
    };

    const newList = artisans.map(a => {
      if (a.id === user.artisanId) {
        return { ...a, pendingChanges: edits };
      }
      return a;
    });
    onUpdateArtisans(newList);
    setSuccessMsg('Profile updates submitted for admin review.');
    setActiveTab('overview');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const handleAddArtwork = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newAW: Artwork = {
      id: `aw-${Date.now()}`,
      title: formData.get('title') as string,
      description: formData.get('description') as string,
      price: formData.get('price') as string,
      image: 'https://images.unsplash.com/photo-1598300042247-d088f8ab3a91?w=800&fit=crop', // Mock image
      status: 'pending'
    };

    const newList = artisans.map(a => {
      if (a.id === user.artisanId) {
        return { ...a, artworks: [...a.artworks, newAW] };
      }
      return a;
    });
    onUpdateArtisans(newList);
    setSuccessMsg('New artwork submitted for admin review.');
    setActiveTab('overview');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  return (
    <div className="bg-[#cab89d] min-h-screen py-10 px-4 md:px-20 max-w-[1440px] mx-auto">
      {/* Dashboard Header */}
      <div className="flex flex-col md:flex-row justify-between items-end mb-10 border-b border-[#D6C7B2] pb-8 gap-6">
        <div>
          <h1 className="text-4xl md:text-5xl font-playfair text-[#3E2D1F] mb-2 uppercase tracking-tight">
            {user.role === 'admin' ? 'Admin Control Center' : 'Artisan Workspace'}
          </h1>
          <p className="font-lora italic text-[#5A4632]">
            Welcome back, <span className="font-bold text-[#4B3827]">{user.name}</span>. Accessing archive as <span className="uppercase text-xs font-bold px-2 py-0.5 bg-[#4B3827] text-white rounded-full">{user.role}</span>
          </p>
        </div>

        <div className="flex gap-2">
           <button 
             onClick={() => setActiveTab('overview')}
             className={`px-6 py-2 text-xs font-bold uppercase tracking-widest border-b-2 transition-all ${activeTab === 'overview' ? 'border-[#7B4A2E] text-[#7B4A2E]' : 'border-transparent text-[#8A7660] hover:text-[#4B3827]'}`}
           >
             Overview
           </button>
           {user.role === 'admin' ? (
              <button 
                onClick={() => setActiveTab('review')}
                className={`relative px-6 py-2 text-xs font-bold uppercase tracking-widest border-b-2 transition-all ${activeTab === 'review' ? 'border-[#7B4A2E] text-[#7B4A2E]' : 'border-transparent text-[#8A7660] hover:text-[#4B3827]'}`}
              >
                Pending Review
                {pendingRequests.length > 0 && (
                  <span className="absolute -top-1 -right-1 w-4 h-4 bg-[#7B4A2E] text-white text-[10px] flex items-center justify-center rounded-full animate-bounce">
                    {pendingRequests.length}
                  </span>
                )}
