          ) : (
            <button 
              onClick={() => handleLinkClick('login')}
              className="bg-[#3E2D1F] text-[#F5F1EA] px-6 py-2 text-xs font-bold uppercase tracking-widest hover:bg-black transition-all rounded-sm shadow-md"
            >
              Login
