          {isMenuOpen ? (
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          ) : (
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16m-7 6h7" />
            </svg>
          )}
        </button>
      </div>

      {/* Mobile Menu Overlay */}
      {isMenuOpen && (
        <div className="md:hidden bg-[#F2E6D8] border-b border-[#D6C7B2] absolute w-full left-0 p-6 flex flex-col gap-4 shadow-xl animate-fade-in z-50">
          <button onClick={() => handleLinkClick('art-forms')} className="text-left text-lg font-playfair text-[#3E2D1F] py-2 border-b border-black/5">Art Forms</button>
          <button onClick={() => handleLinkClick('artists')} className="text-left text-lg font-playfair text-[#3E2D1F] py-2 border-b border-black/5">Artists</button>

          {user ? (
             <>
               <button onClick={() => handleLinkClick('dashboard')} className="text-left text-sm font-bold uppercase tracking-widest text-[#7B4A2E] py-2">My Dashboard</button>
               <button onClick={onLogout} className="text-left text-sm font-bold uppercase tracking-widest text-[#4B3827] py-2">Logout</button>
             </>
          ) : (
             <button 
               onClick={() => handleLinkClick('login')} 
               className="text-left text-sm font-bold uppercase tracking-widest text-[#3E2D1F] py-2"
             >
               Login
             </button>
          )}
        </div>
      )}
    </header>
  );
};

export default Navbar;

import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import HomePage from './pages/HomePage';
import ArtFormDetailPage from './pages/ArtFormDetailPage';
import ArtisanDetailPage from './pages/ArtisanDetailPage';
import ExplorePage from './pages/ExplorePage';
import ArtFormsPage from './pages/ArtFormsPage';
import ArtistsPage from './pages/ArtistsPage';
import LoginPage from './pages/LoginPage';
import DashboardPage from './pages/DashboardPage';
import { ART_FORMS, ARTISANS as INITIAL_ARTISANS } from './constants';
import { Artisan, User } from './types';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<string>('home');
  const [user, setUser] = useState<User | null>(null);
  const [allArtisans, setAllArtisans] = useState<Artisan[]>(INITIAL_ARTISANS.map(a => ({...a, status: 'live'})));

  const [selectedArtFormId, setSelectedArtFormId] = useState<string | null>(null);
  const [selectedArtisanId, setSelectedArtisanId] = useState<string | null>(null);
  const [artisanFilterIntent, setArtisanFilterIntent] = useState<string | null>(null);

  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, [currentPage, selectedArtFormId, selectedArtisanId]);

  const handleNavigate = (page: string) => {
    setCurrentPage(page);
    setSelectedArtFormId(null);
    setSelectedArtisanId(null);
    if (page !== 'artists') {
      setArtisanFilterIntent(null);
    }
  };

  const handleArtFormSelect = (id: string) => {
    setSelectedArtFormId(id);
    setSelectedArtisanId(null);
    setCurrentPage('detail');
  };

  const handleArtisanSelect = (id: string) => {
    setSelectedArtisanId(id);
    setSelectedArtFormId(null);
    setCurrentPage('artisan-detail');
  };

  const handleExploreArtisans = (craftName: string) => {
    setArtisanFilterIntent(craftName);
    setCurrentPage('artists');
  };

  const handleLogin = (newUser: User) => {
    setUser(newUser);
    setCurrentPage('dashboard');
  };

  const handleLogout = () => {
    setUser(null);
    setCurrentPage('home');
  };

  const handleUpdateArtisans = (updatedList: Artisan[]) => {
    setAllArtisans(updatedList);
  };

  const currentArtForm = ART_FORMS.find(f => f.id === selectedArtFormId);
  const currentArtisan = allArtisans.find(a => a.id === selectedArtisanId);

  return (
    <div className="min-h-screen flex flex-col bg-[#cab89d] selection:bg-[#7B4A2E] selection:text-white">
      <Navbar 
        onNavigate={handleNavigate} 
        currentPage={currentPage} 
        user={user}
        onLogout={handleLogout}
      />

      <main className="flex-grow">
        {currentPage === 'home' && (
          <HomePage 
            onArtFormSelect={handleArtFormSelect} 
            onArtisanSelect={handleArtisanSelect}
            artisans={allArtisans.filter(a => a.status === 'live')}
          />
        )}

        {currentPage === 'explore' && (
          <ExplorePage 
            onArtFormSelect={handleArtFormSelect} 
            onArtisanSelect={handleArtisanSelect}
            artisans={allArtisans.filter(a => a.status === 'live')}
          />
        )}

        {currentPage === 'art-forms' && (
          <ArtFormsPage 
            onArtFormSelect={handleArtFormSelect}
          />
        )}

        {currentPage === 'artists' && (
          <ArtistsPage 
            onArtisanSelect={handleArtisanSelect}
            preAppliedCraft={artisanFilterIntent}
            artisans={allArtisans.filter(a => a.status === 'live')}
          />
        )}

        {currentPage === 'detail' && currentArtForm && (
          <ArtFormDetailPage 
            artForm={currentArtForm} 
            onBack={() => handleNavigate('art-forms')} 
            onExploreArtisans={handleExploreArtisans}
            onArtisanSelect={handleArtisanSelect}
            artisans={allArtisans.filter(a => a.status === 'live')}
          />
        )}

        {currentPage === 'artisan-detail' && currentArtisan && (
          <ArtisanDetailPage 
            artisan={currentArtisan} 
            onBack={() => handleNavigate('artists')} 
          />
        )}

        {currentPage === 'login' && (
          <LoginPage onLogin={handleLogin} />
        )}

        {currentPage === 'dashboard' && user && (
          <DashboardPage 
            user={user} 
            artisans={allArtisans} 
            onUpdateArtisans={handleUpdateArtisans}
          />
        )}
      </main>

      <Footer />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import Hero from '../components/Hero';
import { ArtForm, Artisan } from '../types';

interface ArtFormDetailPageProps {
  artForm: ArtForm;
  onBack: () => void;
  onExploreArtisans: (craftName: string) => void;
  onArtisanSelect: (id: string) => void;
  artisans: Artisan[];
}

const ArtFormDetailPage: React.FC<ArtFormDetailPageProps> = ({ artForm, onBack, onExploreArtisans, onArtisanSelect, artisans }) => {
  const [displayText, setDisplayText] = useState('');
  const [isExpanded, setIsExpanded] = useState(false);
  const typingRef = useRef<any>(null);

  const truncatedText = artForm.fullDescription.slice(0, 150) + "...";
  const fullText = artForm.fullDescription;

  useEffect(() => {
    setDisplayText(truncatedText);
    return () => {
      if (typingRef.current) clearTimeout(typingRef.current);
    };
  }, [artForm, truncatedText]);

  const handleToggle = () => {
    if (!isExpanded) {
      let currentText = truncatedText;
      let charIndex = 150;
      const type = () => {
        if (charIndex < fullText.length) {
          currentText += fullText[charIndex];
          setDisplayText(currentText);
          charIndex++;
          typingRef.current = setTimeout(type, 15);
        } else {
          setIsExpanded(true);
        }
      };
      type();
    } else {
      setDisplayText(truncatedText);
      setIsExpanded(false);
      if (typingRef.current) clearTimeout(typingRef.current);
    }
  };

  const relevantArtisans = artisans.filter(a => a.role.toLowerCase().includes(artForm.name.toLowerCase().split(' ')[0].toLowerCase()));

  if (!artForm) return null;

  return (
    <div className="bg-[#cab89d] min-h-screen">
      <Hero 
        title={artForm.name}
        subtitle={`The traditional Kashmiri ${artForm.name} craft.`}
        image={artForm.image}
        compact
      />

      <main className="max-w-[1300px] mx-auto px-4 md:px-6 py-12 md:py-16">
        <section className="flex flex-col lg:flex-row gap-8 md:gap-12 mb-16 md:mb-20">
          <div className="flex-1 order-2 lg:order-1">
            <h2 className="text-3xl md:text-4xl font-playfair text-[#7b4f3a] mb-6">About {artForm.name}</h2>
            <div className="relative font-lora text-base md:text-lg leading-relaxed text-[#4B3827]">
              <p className="mb-4">{displayText}</p>
              <button 
                onClick={handleToggle}
                className="text-[#7b4f3a] font-bold hover:underline transition-all flex items-center gap-2 mt-4 text-sm md:text-base"
              >
                {isExpanded ? 'Read Less ▲' : 'Read More >>>'}
              </button>
            </div>
          </div>
          <div className="flex-1 order-1 lg:order-2">
            <img 
              src={artForm.image} 
              alt={artForm.name} 
              className="w-full h-[300px] md:h-[400px] object-cover border-4 md:border-[10px] border-white/20 shadow-xl rounded-sm"
            />
          </div>
        </section>

        {relevantArtisans.length > 0 && (
          <section className="mb-10">
            <h2 className="text-2xl md:text-3xl font-playfair text-[#7b4f3a] mb-8 md:mb-10 tracking-widest uppercase border-l-4 border-[#7b4f3a] pl-4">Masters of the Craft</h2>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 md:gap-6">
              {relevantArtisans.slice(0, 4).map((artisan, idx) => (
                <div 
                  key={idx} 
                  onClick={() => onArtisanSelect(artisan.id)}
                  className="bg-white/60 p-4 shadow-sm text-center rounded-sm cursor-pointer hover:bg-white/80 hover:shadow-md active:scale-95 transition-all group"
                >
                  <div className="w-20 h-20 md:w-32 md:h-32 rounded-full mx-auto overflow-hidden mb-4 border-2 border-[#D6C7B2]">
                    <img src={artisan.image} alt={artisan.name} className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-500" />
                  </div>
                  <h5 className="text-base md:text-lg font-bold text-[#3E2D1F] mb-1 font-playfair group-hover:text-[#7b4f3a] transition-colors">{artisan.name}</h5>
                  <p className="text-[10px] md:text-xs text-[#7a6041] uppercase tracking-wider font-bold">{artisan.experience}</p>
                </div>
              ))}
            </div>

            <div className="text-center mt-10">
              <button 
                onClick={() => onExploreArtisans(artForm.name)}
                className="bg-transparent border-2 border-[#7b4f3a] text-[#7b4f3a] px-8 py-3 font-bold tracking-widest uppercase text-xs hover:bg-[#7b4f3a] hover:text-white transition-all rounded-sm shadow-md active:scale-95"
              >
                See all artisans from this art
              </button>
            </div>
          </section>
        )}

        <div className="text-center mt-12 md:mt-20">
          <button 
            onClick={onBack}
            className="text-[#7b4f3a] font-bold border-b-2 border-[#7b4f3a] pb-1 hover:text-[#3E2D1F] hover:border-[#3E2D1F] transition-all font-lora tracking-widest uppercase text-sm"
          >
            ← Back to Art Forms
          </button>
        </div>
      </main>
    </div>
  );
};

export default ArtFormDetailPage;

import React, { useState, useEffect } from 'react';
import { ART_FORMS } from '../constants';
import { Artisan } from '../types';

interface ArtistsPageProps {
  onArtisanSelect: (id: string) => void;
  artisans: Artisan[];
  preAppliedCraft?: string | null;
}

const ArtistsPage: React.FC<ArtistsPageProps> = ({ onArtisanSelect, artisans, preAppliedCraft }) => {
  const [isFilterOpen, setIsFilterOpen] = useState(false);
  const [filters, setFilters] = useState({
    craft: preAppliedCraft || 'all',
    ageRange: 'all',
    location: 'all',
    artworks: 'all',
    experience: 'all'
  });

  useEffect(() => {
    if (preAppliedCraft) {
      setFilters(f => ({ ...f, craft: preAppliedCraft }));
    }
  }, [preAppliedCraft]);

  const handleFilterChange = (key: string, value: string) => {
    setFilters(f => ({ ...f, [key]: value }));
  };

  const clearFilters = () => {
    setFilters({
      craft: 'all',
      ageRange: 'all',
      location: 'all',
      artworks: 'all',
      experience: 'all'
    });
  };

  const filteredArtisans = artisans.filter(artisan => {
    const craftMatch = filters.craft === 'all' || artisan.role.toLowerCase().includes(filters.craft.toLowerCase());

    let ageMatch = true;
    if (filters.ageRange === '30-45') ageMatch = artisan.age >= 30 && artisan.age <= 45;
    if (filters.ageRange === '46-60') ageMatch = artisan.age >= 46 && artisan.age <= 60;
    if (filters.ageRange === '60+') ageMatch = artisan.age > 60;

    const locationMatch = filters.location === 'all' || artisan.location === filters.location;

    let artworksMatch = true;
    if (filters.artworks === '0-50') artworksMatch = artisan.artworksCount <= 50;
    if (filters.artworks === '51-150') artworksMatch = artisan.artworksCount > 50 && artisan.artworksCount <= 150;
    if (filters.artworks === '150+') artworksMatch = artisan.artworksCount > 150;

    let experienceMatch = true;
    if (filters.experience === '0-20') experienceMatch = artisan.experienceYears <= 20;
    if (filters.experience === '21-35') experienceMatch = artisan.experienceYears > 20 && artisan.experienceYears <= 35;
    if (filters.experience === '35+') experienceMatch = artisan.experienceYears > 35;

    return craftMatch && ageMatch && locationMatch && artworksMatch && experienceMatch;
  });

  const locations = Array.from(new Set(artisans.map(a => a.location)));
  const hasActiveFilters = Object.values(filters).some(v => v !== 'all');

  return (
    <div className="bg-[#cab89d] min-h-screen">
      <section className="pt-12 pb-6 px-6 max-w-[1440px] mx-auto">
        <div className="text-center mb-10">
          <h1 className="text-5xl md:text-6xl font-playfair text-[#3E2D1F] mb-4">Master Artists</h1>
          <p className="text-lg font-lora italic text-[#5A4632]">Explore the heritage of Kashmir through its most skilled creators.</p>
        </div>

        {/* --- UNIQUE COLLAPSIBLE FILTER BAR --- */}
        <div className="mb-12">
          <div className="flex flex-col md:flex-row items-center justify-between border-y border-[#4B3827]/10 py-4 mb-4 gap-4">
            <div className="flex items-center gap-6">
              <button 
                onClick={() => setIsFilterOpen(!isFilterOpen)}
                className={`flex items-center gap-3 px-6 py-2.5 transition-all rounded-sm border ${
                  isFilterOpen ? 'bg-[#3E2D1F] text-white border-[#3E2D1F]' : 'bg-[#F2E6D8]/40 border-[#D6C7B2] text-[#3E2D1F] hover:bg-white/60'
                }`}
              >
                <svg className={`w-4 h-4 transition-transform duration-300 ${isFilterOpen ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4" />
                </svg>
                <span className="text-xs font-bold uppercase tracking-[0.2em]">{isFilterOpen ? 'Close Filters' : 'Filter Archive'}</span>
              </button>

              <div className="hidden lg:block text-[10px] font-bold uppercase tracking-[0.3em] text-[#8A7660]">
                Showing {filteredArtisans.length} of {artisans.length} Masters
              </div>
            </div>

            {hasActiveFilters && (
              <button 
                onClick={clearFilters}
                className="text-[10px] font-bold uppercase tracking-widest text-[#7B4A2E] hover:text-[#3E2D1F] underline decoration-dotted underline-offset-4"
              >
                Clear All Parameters
              </button>
            )}
          </div>

          {/* Expanded Filter Panel */}
          <div className={`overflow-hidden transition-all duration-500 ease-in-out ${isFilterOpen ? 'max-h-[800px] opacity-100 mb-10' : 'max-h-0 opacity-0 pointer-events-none'}`}>
            <div className="bg-[#F2E6D8] border border-[#D6C7B2] p-8 md:p-12 shadow-2xl grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-8">
              <div className="space-y-3">
                <label className="block text-[10px] font-bold uppercase tracking-[0.2em] text-[#7B4A2E]">Craft Tradition</label>
                <select 
                  value={filters.craft}
                  onChange={(e) => handleFilterChange('craft', e.target.value)}
                  className="w-full bg-white/80 border border-[#D6C7B2] p-3 text-xs font-lora focus:outline-none focus:ring-1 focus:ring-[#7B4A2E] cursor-pointer"
                >
                  <option value="all">All Traditions</option>
                  {ART_FORMS.map(af => (
                    <option key={af.id} value={af.name}>{af.name}</option>
                  ))}
                </select>
              </div>

              <div className="space-y-3">
                <label className="block text-[10px] font-bold uppercase tracking-[0.2em] text-[#7B4A2E]">Age Group</label>
                <select 
                  value={filters.ageRange}
                  onChange={(e) => handleFilterChange('ageRange', e.target.value)}
                  className="w-full bg-white/80 border border-[#D6C7B2] p-3 text-xs font-lora focus:outline-none focus:ring-1 focus:ring-[#7B4A2E] cursor-pointer"
                >
                  <option value="all">Any Age</option>
                  <option value="30-45">30 - 45 Years</option>
                  <option value="46-60">46 - 60 Years</option>
                  <option value="60+">60+ Years</option>
                </select>
              </div>

              <div className="space-y-3">
                <label className="block text-[10px] font-bold uppercase tracking-[0.2em] text-[#7B4A2E]">Region</label>
                <select 
                  value={filters.location}
                  onChange={(e) => handleFilterChange('location', e.target.value)}
                  className="w-full bg-white/80 border border-[#D6C7B2] p-3 text-xs font-lora focus:outline-none focus:ring-1 focus:ring-[#7B4A2E] cursor-pointer"
                >
                  <option value="all">All Districts</option>
                  {locations.map(loc => (
                    <option key={loc} value={loc}>{loc}</option>
                  ))}
                </select>
              </div>

              <div className="space-y-3">
                <label className="block text-[10px] font-bold uppercase tracking-[0.2em] text-[#7B4A2E]">Experience</label>
                <select 
                  value={filters.experience}
                  onChange={(e) => handleFilterChange('experience', e.target.value)}
                  className="w-full bg-white/80 border border-[#D6C7B2] p-3 text-xs font-lora focus:outline-none focus:ring-1 focus:ring-[#7B4A2E] cursor-pointer"
                >
                  <option value="all">Any Experience</option>
                  <option value="0-20">Under 20 Years</option>
                  <option value="21-35">21 - 35 Years</option>
                  <option value="35+">35+ Years</option>
                </select>
              </div>

              <div className="space-y-3">
                <label className="block text-[10px] font-bold uppercase tracking-[0.2em] text-[#7B4A2E]">Workload</label>
                <select 
                  value={filters.artworks}
                  onChange={(e) => handleFilterChange('artworks', e.target.value)}
                  className="w-full bg-white/80 border border-[#D6C7B2] p-3 text-xs font-lora focus:outline-none focus:ring-1 focus:ring-[#7B4A2E] cursor-pointer"
                >
                  <option value="all">Any Count</option>
                  <option value="0-50">Up to 50 Works</option>
                  <option value="51-150">51 - 150 Works</option>
                  <option value="150+">150+ Works</option>
                </select>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* --- CONTENT SECTION --- */}
      <section className="max-w-[1440px] mx-auto px-4 md:px-20 pb-24">
        {filteredArtisans.length > 0 ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-10">
            {filteredArtisans.map((artisan: Artisan) => (
              <div 
                key={artisan.id} 
                onClick={() => { if(window.innerWidth < 768) onArtisanSelect(artisan.id) }}
                className="relative bg-[#F2E6D8] border border-[#D6C7B2] flex flex-col group overflow-hidden shadow-lg h-[480px] rounded-sm cursor-pointer"
              >
                <img 
                  src={artisan.image} 
                  alt={artisan.name} 
                  className="w-full h-full object-cover grayscale transition-all duration-1000 md:group-hover:grayscale-0 md:group-hover:scale-105"
                />

                <div className="absolute bottom-0 left-0 w-full bg-gradient-to-t from-black/95 via-black/70 to-transparent p-6 transition-transform duration-500 md:group-hover:translate-y-full">
                  <h4 className="text-2xl font-normal text-[#F5F1EA] mb-1 font-playfair">{artisan.name}</h4>
                  <p className="text-xs text-[#E2D7C6] italic font-lora tracking-widest uppercase">{artisan.role}</p>
                  <div className="mt-3 flex gap-4">
                    <span className="text-[10px] text-white/60 font-bold uppercase">{artisan.experienceYears}Y Exp.</span>
                    <span className="text-[10px] text-white/60 font-bold uppercase">{artisan.location}</span>
                  </div>
                </div>

                <div className="hidden md:flex absolute inset-0 bg-[#3E2D1F]/90 backdrop-blur-[4px] opacity-0 group-hover:opacity-100 transition-all duration-500 p-8 flex-col justify-center items-center text-center">
                  <h4 className="text-2xl font-normal text-[#F5F1EA] mb-1 font-playfair transform translate-y-4 opacity-0 transition-all duration-500 delay-75 group-hover:translate-y-0 group-hover:opacity-100">
                    {artisan.name}
                  </h4>
                  <p className="text-[#D6C7B2] font-semibold mb-3 tracking-[0.1em] uppercase text-[10px] font-lora transform translate-y-4 opacity-0 transition-all duration-500 delay-100 group-hover:translate-y-0 group-hover:opacity-100">
                    {artisan.role}
                  </p>
                  <div className="w-12 h-[1px] bg-[#D6C7B2]/40 mb-4 transform scale-x-0 transition-transform duration-500 delay-150 group-hover:scale-x-100" />

                  <p className="text-sm text-[#E2D7C6] leading-relaxed mb-6 font-lora italic px-2 transform translate-y-4 opacity-0 transition-all duration-500 delay-200 group-hover:translate-y-0 group-hover:opacity-100">
                    "{artisan.bio}"
                  </p>

                  <div className="text-[10px] text-[#8A7660] mb-8 uppercase tracking-[0.2em] font-bold transform translate-y-4 opacity-0 transition-all duration-500 delay-300 group-hover:translate-y-0 group-hover:opacity-100">
                    {artisan.experience} • {artisan.artworksCount} Works
                  </div>

                  <button 
                    onClick={(e) => { e.stopPropagation(); onArtisanSelect(artisan.id); }}
                    className="px-8 py-3 border-2 border-[#F5F1EA] text-[#F5F1EA] hover:bg-[#F5F1EA] hover:text-[#3E2D1F] transition-all duration-700 delay-[400ms] opacity-0 transform translate-y-8 group-hover:opacity-100 group-hover:translate-y-0 text-[10px] tracking-[0.2em] uppercase font-bold active:scale-95"
                  >
                    View Profile
                  </button>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="py-24 text-center bg-[#F2E6D8]/30 border border-dashed border-[#D6C7B2] rounded-sm">
            <h3 className="text-2xl font-playfair italic text-[#7B4A2E] mb-4">No artists match your criteria.</h3>
            <button 
              onClick={clearFilters}
              className="text-xs font-bold uppercase tracking-[0.2em] text-[#3E2D1F] border-b border-[#3E2D1F] pb-1 hover:text-[#7B4A2E] hover:border-[#7B4A2E] transition-colors"
            >
              Reset Archive Filters
            </button>
          </div>
        )}
      </section>
    </div>
  );
};

export default ArtistsPage;

export type Role = 'admin' | 'artisan' | 'guest';

export interface User {
  id: string;
  name: string;
  role: Role;
  artisanId?: string; // Links user to their artisan profile if role is 'artisan'
}

export interface ArtForm {
  id: string;
  name: string;
  shortDescription: string;
  fullDescription: string;
  image: string;
  process?: ProcessStep[];
  products?: Product[];
}

export interface ProcessStep {
  title: string;
  description: string;
  image: string;
}

export interface Product {
  name: string;
  image: string;
}

export interface MediaProof {
  id: string;
  title: string;
  type: 'image' | 'document';
  url: string;
  status: 'pending' | 'approved' | 'rejected';
}

export interface Artwork {
  id: string;
  title: string;
  description: string;
  price: string;
  image: string;
  status: 'pending' | 'live' | 'rejected';
}

export interface Artisan {
  id: string;
  name: string;
  role: string;
  experience: string;
  experienceYears: number;
  age: number;
  location: string;
  artworksCount: number;
  bio: string;
  image: string;
  specialties?: string[];
  status: 'live' | 'pending' | 'suspended';
  mediaProof?: MediaProof[];
  pendingChanges?: Partial<Artisan>; // Stores edits waiting for admin approval
  rejectionNote?: string; // Stores reason for latest rejection
  artworks: Artwork[];
}

import React, { useState } from 'react';
import { User, Artisan, Artwork } from '../types';
import { ART_FORMS } from '../constants';

interface DashboardPageProps {
  user: User;
  artisans: Artisan[];
  onUpdateArtisans: (list: Artisan[]) => void;
}

const DashboardPage: React.FC<DashboardPageProps> = ({ user, artisans, onUpdateArtisans }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'review' | 'edit' | 'artworks'>('overview');
  const [successMsg, setSuccessMsg] = useState('');
  const [rejectingId, setRejectingId] = useState<string | null>(null);
  const [rejectionReason, setRejectionReason] = useState('');

  // Find target artisan if role is artisan
  const myProfile = artisans.find(a => a.id === user.artisanId);

  // Pending tasks for admin
  const pendingRequests = artisans.filter(a => 
    a.status === 'pending' || 
    a.pendingChanges || 
    a.artworks.some(aw => aw.status === 'pending')
  );

  const handleApproveProfile = (artisanId: string) => {
    const newList = artisans.map(a => {
      if (a.id === artisanId) {
        if (a.status === 'pending') return { ...a, status: 'live' as const, rejectionNote: undefined };
        if (a.pendingChanges) {
          const updated = { ...a, ...a.pendingChanges, pendingChanges: undefined, rejectionNote: undefined };
          return updated as Artisan;
        }
      }
      return a;
    });
    onUpdateArtisans(newList);
    setSuccessMsg('Profile changes approved.');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const handleRejectProfile = (artisanId: string) => {
    if (!rejectionReason.trim()) return;

    const newList = artisans.map(a => {
      if (a.id === artisanId) {
        return { 
          ...a, 
          pendingChanges: undefined, 
          rejectionNote: rejectionReason,
          status: a.status === 'pending' ? 'suspended' : a.status // Suspend if it was a new application
        } as Artisan;
      }
      return a;
    });

    onUpdateArtisans(newList);
    setRejectingId(null);
    setRejectionReason('');
    setSuccessMsg('Profile changes rejected with reason.');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const handleApproveArtwork = (artisanId: string, artworkId: string) => {
    const newList = artisans.map(a => {
      if (a.id === artisanId) {
        return {
          ...a,
          artworks: a.artworks.map(aw => aw.id === artworkId ? { ...aw, status: 'live' as const } : aw)
        };
      }
      return a;
    });
    onUpdateArtisans(newList);
    setSuccessMsg('Artwork approved and added to live gallery.');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const handleRejectArtwork = (artisanId: string, artworkId: string) => {
    const newList = artisans.map(a => {
      if (a.id === artisanId) {
        return {
          ...a,
          artworks: a.artworks.map(aw => aw.id === artworkId ? { ...aw, status: 'rejected' as const } : aw)
        };
      }
      return a;
    });
    onUpdateArtisans(newList);
  };

  const handleArtisanSubmitEdits = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const edits = {
      bio: formData.get('bio') as string,
      location: formData.get('location') as string,
    };

    const newList = artisans.map(a => {
      if (a.id === user.artisanId) {
        return { ...a, pendingChanges: edits };
      }
      return a;
    });
    onUpdateArtisans(newList);
    setSuccessMsg('Profile updates submitted for admin review.');
    setActiveTab('overview');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const handleAddArtwork = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newAW: Artwork = {
      id: `aw-${Date.now()}`,
      title: formData.get('title') as string,
      description: formData.get('description') as string,
      price: formData.get('price') as string,
      image: 'https://images.unsplash.com/photo-1598300042247-d088f8ab3a91?w=800&fit=crop', // Mock image
      status: 'pending'
    };

    const newList = artisans.map(a => {
      if (a.id === user.artisanId) {
        return { ...a, artworks: [...a.artworks, newAW] };
      }
      return a;
    });
    onUpdateArtisans(newList);
    setSuccessMsg('New artwork submitted for admin review.');
    setActiveTab('overview');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  return (
    <div className="bg-[#cab89d] min-h-screen py-10 px-4 md:px-20 max-w-[1440px] mx-auto">
      {/* Dashboard Header */}
      <div className="flex flex-col md:flex-row justify-between items-end mb-10 border-b border-[#4B3827]/10 pb-8 gap-6">
        <div>
          <h1 className="text-4xl md:text-5xl font-playfair text-[#3E2D1F] mb-2 uppercase tracking-tight">
            {user.role === 'admin' ? 'Archive Registry' : 'Artisan Workspace'}
          </h1>
          <p className="font-lora italic text-[#5A4632]">
            Logged in as <span className="font-bold text-[#4B3827]">{user.name}</span> <span className="text-[10px] bg-[#3E2D1F] text-[#F5F1EA] px-2 py-0.5 ml-2 font-black uppercase tracking-widest">{user.role}</span>
          </p>
        </div>

        <div className="flex gap-2">
           <button 
             onClick={() => setActiveTab('overview')}
             className={`px-6 py-2 text-[10px] font-bold uppercase tracking-[0.2em] border-b-2 transition-all ${activeTab === 'overview' ? 'border-[#7B4A2E] text-[#7B4A2E]' : 'border-transparent text-[#8A7660] hover:text-[#4B3827]'}`}
           >
             Snapshot
           </button>
           {user.role === 'admin' ? (
              <button 
                onClick={() => setActiveTab('review')}
                className={`relative px-6 py-2 text-[10px] font-bold uppercase tracking-[0.2em] border-b-2 transition-all ${activeTab === 'review' ? 'border-[#7B4A2E] text-[#7B4A2E]' : 'border-transparent text-[#8A7660] hover:text-[#4B3827]'}`}
              >
                Review Log
                {pendingRequests.length > 0 && (
                  <span className="absolute -top-1 -right-1 w-4 h-4 bg-[#7B4A2E] text-white text-[9px] flex items-center justify-center rounded-full animate-pulse">
                    {pendingRequests.length}
                  </span>
                )}
              </button>
           ) : (
              <>
                <button 
                  onClick={() => setActiveTab('edit')}
                  className={`px-6 py-2 text-[10px] font-bold uppercase tracking-[0.2em] border-b-2 transition-all ${activeTab === 'edit' ? 'border-[#7B4A2E] text-[#7B4A2E]' : 'border-transparent text-[#8A7660] hover:text-[#4B3827]'}`}
                >
                  Edit Profile
                </button>
                <button 
                  onClick={() => setActiveTab('artworks')}
                  className={`px-6 py-2 text-[10px] font-bold uppercase tracking-[0.2em] border-b-2 transition-all ${activeTab === 'artworks' ? 'border-[#7B4A2E] text-[#7B4A2E]' : 'border-transparent text-[#8A7660] hover:text-[#4B3827]'}`}
                >
                  Gallery
                </button>
              </>
           )}
        </div>
      </div>

      {successMsg && (
        <div className="mb-8 p-4 bg-green-50 border-l-4 border-green-500 text-green-800 text-xs font-bold flex items-center gap-3 animate-fade-in shadow-sm">
           <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg>
           {successMsg}
        </div>
      )}

      {/* --- ADMIN VIEW: REVIEW --- */}
      {user.role === 'admin' && activeTab === 'review' && (
        <section className="space-y-8 animate-fade-in">
           <h2 className="text-2xl font-playfair text-[#3E2D1F] border-l-4 border-[#7B4A2E] pl-4 mb-8">Registry Task Queue</h2>
           {pendingRequests.length > 0 ? (
             <div className="grid grid-cols-1 gap-8">
                {pendingRequests.map(artisan => (
                  <div key={artisan.id} className="bg-[#F2E6D8] p-8 border border-[#D6C7B2] shadow-md flex flex-col gap-6 relative overflow-hidden">
                    <div className="flex flex-col md:flex-row gap-10 items-start">
                      <div className="w-24 h-24 rounded-full overflow-hidden border-2 border-[#D6C7B2] shrink-0">
                        <img src={artisan.image} className="w-full h-full object-cover" alt="" />
                      </div>
                      <div className="flex-grow">
                        <div className="flex items-center gap-4 mb-3">
                          <h3 className="text-2xl font-bold font-playfair text-[#3E2D1F]">{artisan.name}</h3>
                          <span className="text-[9px] bg-[#7B4A2E] text-white px-2 py-0.5 font-black uppercase tracking-[0.2em]">
                            {artisan.pendingChanges ? 'Profile Update' : artisan.status === 'pending' ? 'Verification' : 'Catalog Audit'}
                          </span>
                        </div>
                        <p className="text-sm font-lora italic text-[#5A4632] mb-6">Traditional practitioner of {artisan.role}</p>

                        {(artisan.status === 'pending' || artisan.pendingChanges) && (
                          <div className="mb-8">
                            {artisan.pendingChanges && (
                              <div className="bg-white/40 p-5 border border-[#D6C7B2] mb-6">
                                <p className="text-[10px] font-bold uppercase tracking-widest text-[#8A7660] mb-3">Change Request Details:</p>
                                <ul className="text-xs space-y-3 font-lora">
                                    {Object.entries(artisan.pendingChanges).map(([key, val]) => (
                                      <li key={key} className="flex gap-2">
                                        <span className="font-bold text-[#3E2D1F] capitalize">{key}:</span>
                                        <span className="text-[#5A4632]">{val as string}</span>
                                      </li>
                                    ))}
                                </ul>
                              </div>
                            )}

                            {rejectingId === artisan.id ? (
                               <div className="bg-[#E2D7C6] p-5 border border-[#7B4A2E]/30 animate-fade-in">
                                  <label className="block text-[10px] font-bold uppercase tracking-widest text-[#7B4A2E] mb-2">Reason for Rejection</label>
                                  <textarea 
                                    value={rejectionReason}
                                    onChange={(e) => setRejectionReason(e.target.value)}
                                    placeholder="Please provide guidance for the artisan..."
                                    className="w-full bg-white border border-[#D6C7B2] p-3 text-xs font-lora focus:outline-none focus:ring-1 focus:ring-[#7B4A2E] mb-4"
                                    rows={3}
                                  />
                                  <div className="flex gap-2">
                                    <button 
                                      onClick={() => handleRejectProfile(artisan.id)}
                                      className="bg-[#7B4A2E] text-white px-6 py-2 text-[10px] font-bold uppercase tracking-widest hover:bg-[#3E2D1F] transition-all"
                                    >
                                      Confirm Rejection
                                    </button>
                                    <button 
                                      onClick={() => { setRejectingId(null); setRejectionReason(''); }}
                                      className="text-[10px] font-bold uppercase tracking-widest text-[#3E2D1F] px-4"
                                    >
                                      Cancel
                                    </button>
                                  </div>
                               </div>
                            ) : (
                               <div className="flex gap-3">
                                  <button 
                                    onClick={() => handleApproveProfile(artisan.id)}
                                    className="bg-[#3E2D1F] text-[#F5F1EA] px-8 py-2.5 text-[10px] font-bold uppercase tracking-[0.2em] hover:bg-black transition-all shadow-md"
                                  >
                                    Approve Changes
                                  </button>
                                  <button 
                                    onClick={() => setRejectingId(artisan.id)}
                                    className="border-2 border-[#7B4A2E] text-[#7B4A2E] px-8 py-2 text-[10px] font-bold uppercase tracking-[0.2em] hover:bg-[#7B4A2E] hover:text-white transition-all"
                                  >
                                    Reject Changes
                                  </button>
                               </div>
                            )}
                          </div>
                        )}

                        {artisan.artworks.some(aw => aw.status === 'pending') && (
                          <div className="space-y-5 pt-8 border-t border-[#D6C7B2]/40">
                            <p className="text-[10px] font-bold uppercase tracking-widest text-[#8A7660]">New Catalog Submissions:</p>
                            {artisan.artworks.filter(aw => aw.status === 'pending').map(aw => (
                              <div key={aw.id} className="bg-white/60 p-5 border border-[#D6C7B2] flex gap-6 items-center">
                                <img src={aw.image} className="w-20 h-20 object-cover border border-[#D6C7B2]" alt="" />
                                <div className="flex-grow">
                                  <h4 className="font-playfair font-bold text-lg text-[#3E2D1F]">{aw.title}</h4>
                                  <p className="text-xs font-lora text-[#5A4632]">{aw.price}</p>
                                </div>
                                <div className="flex gap-2">
                                  <button onClick={() => handleApproveArtwork(artisan.id, aw.id)} className="px-5 py-2 bg-green-800 text-white text-[9px] font-bold uppercase tracking-widest hover:bg-green-900">Approve</button>
                                  <button onClick={() => handleRejectArtwork(artisan.id, aw.id)} className="px-5 py-2 border border-[#7B4A2E] text-[#7B4A2E] text-[9px] font-bold uppercase tracking-widest hover:bg-[#7B4A2E] hover:text-white">Reject</button>
                                </div>
                              </div>
                            ))}
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                ))}
             </div>
           ) : (
             <div className="py-24 text-center border-2 border-dashed border-[#D6C7B2] bg-white/10">
                <p className="font-lora italic text-[#8A7660] text-lg">Your review queue is currently empty. The registry is up to date.</p>
             </div>
           )}
        </section>
      )}

      {/* --- ARTISAN VIEW: ARTWORKS --- */}
      {user.role === 'artisan' && activeTab === 'artworks' && myProfile && (
        <section className="animate-fade-in max-w-5xl">
           <div className="flex justify-between items-center mb-10">
              <h2 className="text-3xl font-playfair text-[#3E2D1F] border-l-4 border-[#7B4A2E] pl-4">Digital Catalog</h2>
           </div>

           <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
              <div className="bg-[#F2E6D8] p-8 border border-[#D6C7B2] shadow-lg">
                <h3 className="text-xl font-playfair mb-8 text-[#3E2D1F]">Submit Heritage Work</h3>
                <form onSubmit={handleAddArtwork} className="space-y-6">
                  <div>
                    <label className="block text-[10px] font-bold uppercase tracking-widest text-[#8A7660] mb-2">Title of Artwork</label>
                    <input name="title" required className="w-full bg-white border border-[#D6C7B2] p-3 text-sm font-lora focus:outline-none focus:ring-1 focus:ring-[#7B4A2E]" />
                  </div>
                  <div>
                    <label className="block text-[10px] font-bold uppercase tracking-widest text-[#8A7660] mb-2">Curatorial Description</label>
                    <textarea name="description" required rows={3} className="w-full bg-white border border-[#D6C7B2] p-3 text-sm font-lora focus:outline-none focus:ring-1 focus:ring-[#7B4A2E]" />
                  </div>
                  <div>
                    <label className="block text-[10px] font-bold uppercase tracking-widest text-[#8A7660] mb-2">Estimated Value</label>
                    <input name="price" placeholder="e.g. ₹15,000" required className="w-full bg-white border border-[#D6C7B2] p-3 text-sm font-lora focus:outline-none focus:ring-1 focus:ring-[#7B4A2E]" />
                  </div>
                  <button type="submit" className="w-full bg-[#3E2D1F] text-[#F5F1EA] py-4 text-[10px] font-bold uppercase tracking-[0.2em] hover:bg-black transition-all shadow-md">Submit for Verification</button>
                </form>
              </div>

              <div className="space-y-5">
                <h3 className="text-xl font-playfair mb-6 text-[#3E2D1F]">Gallery Status</h3>
                {myProfile.artworks.length > 0 ? (
                  myProfile.artworks.map(aw => (
                    <div key={aw.id} className="bg-white/80 p-5 border border-[#D6C7B2] flex gap-6 items-center transition-all hover:bg-white">
                       <img src={aw.image} className="w-20 h-20 object-cover border border-[#D6C7B2]" alt="" />
                       <div className="flex-grow">
                          <h4 className="font-playfair font-bold text-[#3E2D1F] mb-1">{aw.title}</h4>
                          <span className={`text-[8px] uppercase font-black tracking-[0.2em] px-3 py-1 rounded-full ${
                            aw.status === 'live' ? 'bg-green-100 text-green-800' :
                            aw.status === 'pending' ? 'bg-yellow-100 text-yellow-800' :
                            'bg-red-100 text-red-800'
                          }`}>
                            {aw.status}
                          </span>
                       </div>
                       <p className="text-sm font-bold text-[#7B4A2E] font-lora">{aw.price}</p>
                    </div>
                  ))
                ) : (
                  <div className="p-10 text-center border-2 border-dashed border-[#D6C7B2] bg-[#F2E6D8]/20">
                    <p className="text-sm font-lora italic text-[#8A7660]">Your digital gallery is empty.</p>
                  </div>
                )}
              </div>
           </div>
        </section>
      )}

      {/* --- OVERVIEW TAB --- */}
      {activeTab === 'overview' && (
        <section className="grid grid-cols-1 lg:grid-cols-3 gap-10 animate-fade-in">
           <div className="lg:col-span-1">
              <div className="bg-[#4B3827] text-[#F5F1EA] p-10 shadow-2xl sticky top-28 border-t-4 border-[#7B4A2E]">
                 <div className="flex items-center gap-6 mb-10">
                    <div className="w-20 h-20 rounded-full bg-[#7B4A2E] flex items-center justify-center text-4xl font-playfair shadow-xl border border-white/10 ring-4 ring-[#4B3827]">
                       {user.name.charAt(0)}
                    </div>
                    <div>
                       <h3 className="text-2xl font-playfair leading-tight text-white">{user.name}</h3>
                       <p className="text-[10px] uppercase tracking-[0.25em] text-[#D6C7B2] font-black">{user.role}</p>
                    </div>
                 </div>

                 <div className="space-y-8">
                    <div>
                       <p className="text-[9px] uppercase tracking-[0.2em] text-[#8A7660] font-black mb-2">Member Since</p>
                       <p className="text-sm font-lora italic text-[#E2D7C6]">2024 Archive Launch</p>
                    </div>
                    <div>
                       <p className="text-[9px] uppercase tracking-[0.2em] text-[#8A7660] font-black mb-2">Registry Tier</p>
                       <p className="text-sm font-lora text-[#E2D7C6]">{user.role === 'admin' ? 'Master Curator' : 'Heritage Practitioner'}</p>
                    </div>
                    {user.role === 'artisan' && myProfile && (
                      <div>
                         <p className="text-[9px] uppercase tracking-[0.2em] text-[#8A7660] font-black mb-2">Public Visibility</p>
                         <p className="text-sm flex items-center gap-3 text-[#E2D7C6]">
                           <span className={`w-2.5 h-2.5 rounded-full ring-2 ring-white/10 ${myProfile.status === 'live' ? 'bg-green-500' : 'bg-yellow-500 animate-pulse'}`}></span>
                           {myProfile.status === 'live' ? 'Live in Archive' : 'Awaiting Review'}
                         </p>
                         {myProfile.rejectionNote && (
                            <div className="mt-6 p-4 bg-red-900/30 border border-red-500/50 rounded-sm">
                               <p className="text-[9px] uppercase font-black tracking-widest text-red-300 mb-1">Feedback from Curators:</p>
                               <p className="text-xs italic text-red-100 font-lora leading-relaxed">"{myProfile.rejectionNote}"</p>
                            </div>
                         )}
                      </div>
                    )}
                 </div>
              </div>
           </div>

           <div className="lg:col-span-2 space-y-10">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                 <div className="bg-[#F2E6D8] p-8 shadow-md border-b-4 border-[#7B4A2E]">
                    <span className="text-[9px] uppercase font-black tracking-[0.2em] text-[#8A7660]">Masters Catalogued</span>
                    <p className="text-5xl font-playfair mt-3 text-[#3E2D1F]">{artisans.length}</p>
                 </div>
                 <div className="bg-[#F2E6D8] p-8 shadow-md border-b-4 border-[#4B3827]">
                    <span className="text-[9px] uppercase font-black tracking-[0.2em] text-[#8A7660]">Traditions Indexed</span>
                    <p className="text-5xl font-playfair mt-3 text-[#3E2D1F]">{ART_FORMS.length}</p>
                 </div>
                 <div className="bg-[#F2E6D8] p-8 shadow-md border-b-4 border-[#8A7660]">
                    <span className="text-[9px] uppercase font-black tracking-[0.2em] text-[#8A7660]">Moderation Queue</span>
                    <p className="text-5xl font-playfair mt-3 text-[#7B4A2E]">{pendingRequests.length}</p>
                 </div>
              </div>

              <div className="bg-white/40 p-10 border border-[#D6C7B2] rounded-sm">
                 <h3 className="text-2xl font-playfair mb-8 text-[#3E2D1F]">Registry Performance</h3>
                 <div className="space-y-6">
                    <div className="flex justify-between items-center py-4 border-b border-[#4B3827]/10">
                       <span className="text-sm font-lora text-[#5A4632]">Asset Integrity Score</span>
                       <span className="text-[10px] font-black uppercase tracking-widest text-green-700">98.4% Optimal</span>
                    </div>
                    <div className="flex justify-between items-center py-4 border-b border-[#4B3827]/10">
                       <span className="text-sm font-lora text-[#5A4632]">Verification Latency</span>
                       <span className="text-[10px] font-black uppercase tracking-widest text-[#7B4A2E]">~12 Hours</span>
                    </div>
                    <div className="flex justify-between items-center py-4">
                       <span className="text-sm font-lora text-[#5A4632]">Digital Storage Distribution</span>
                       <div className="w-1/3 h-1.5 bg-[#4B3827]/20 rounded-full overflow-hidden">
                          <div className="h-full bg-[#7B4A2E] w-[45%]" />
                       </div>
                    </div>
                 </div>
              </div>
           </div>
        </section>
      )}

      {/* --- EDIT PROFILE VIEW --- */}
      {user.role === 'artisan' && activeTab === 'edit' && myProfile && (
        <section className="animate-fade-in max-w-4xl">
          <h2 className="text-3xl font-playfair text-[#3E2D1F] border-l-4 border-[#7B4A2E] pl-4 mb-10">Archive Identity Maintenance</h2>

          {myProfile.rejectionNote && (
            <div className="mb-8 p-6 bg-red-50 border-l-4 border-red-500 shadow-sm animate-fade-in">
               <p className="text-[10px] font-black uppercase tracking-widest text-red-600 mb-2">Curator Feedback on Previous Attempt:</p>
               <p className="text-sm italic text-[#3E2D1F] font-lora">"{myProfile.rejectionNote}"</p>
            </div>
          )}

          <form onSubmit={handleArtisanSubmitEdits} className="space-y-10 bg-[#F2E6D8] p-10 border border-[#D6C7B2] shadow-xl">
             <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                <div>
                  <label className="block text-[10px] font-bold uppercase tracking-widest text-[#8A7660] mb-3">Workshop Region</label>
                  <input name="location" defaultValue={myProfile.location} className="w-full bg-white border border-[#D6C7B2] p-3 font-lora text-sm focus:outline-none focus:ring-1 focus:ring-[#7B4A2E]" />
                </div>
                <div>
                   <label className="block text-[10px] font-bold uppercase tracking-widest text-[#8A7660] mb-3">Digital Identity Media</label>
                   <div className="flex items-center gap-4">
                      <div className="w-12 h-12 rounded-sm border border-dashed border-[#8A7660] flex items-center justify-center text-[#8A7660]">
                         <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4"></path></svg>
                      </div>
                      <input type="file" className="text-[10px] text-[#5A4632] uppercase font-bold" />
                   </div>
                </div>
             </div>
             <div>
                <label className="block text-[10px] font-bold uppercase tracking-widest text-[#8A7660] mb-3">Professional Statement / Heritage Bio</label>
                <textarea name="bio" defaultValue={myProfile.bio} rows={6} className="w-full bg-white border border-[#D6C7B2] p-4 font-lora text-sm focus:outline-none focus:ring-1 focus:ring-[#7B4A2E] leading-relaxed" />
             </div>
             <button type="submit" className="bg-[#3E2D1F] text-[#F5F1EA] px-16 py-4 text-[11px] font-black uppercase tracking-[0.3em] hover:bg-black hover:shadow-2xl transition-all shadow-lg active:scale-95">Dispatch for Registry Audit</button>
          </form>
        </section>
      )}
    </div>
  );
};

export default DashboardPage;

import React, { useState } from 'react';
import { User, Artisan, Artwork } from '../types';
import { ART_FORMS } from '../constants';

interface DashboardPageProps {
  user: User;
  artisans: Artisan[];
  onUpdateArtisans: (list: Artisan[]) => void;
}

const DashboardPage: React.FC<DashboardPageProps> = ({ user, artisans, onUpdateArtisans }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'review' | 'edit' | 'artworks'>('overview');
  const [successMsg, setSuccessMsg] = useState('');
  const [rejectingId, setRejectingId] = useState<string | null>(null);
  const [rejectionReason, setRejectionReason] = useState('');

  // Find target artisan if role is artisan
  const myProfile = artisans.find(a => a.id === user.artisanId);

  // Artisan notification logic
  const pendingArtworksCount = myProfile?.artworks.filter(aw => aw.status === 'pending').length || 0;
  const hasRejectedArtworks = myProfile?.artworks.some(aw => aw.status === 'rejected') || false;
  const hasPendingProfile = !!myProfile?.pendingChanges;
  const hasRejectedProfile = !!myProfile?.rejectionNote;

  // Pending tasks for admin
  const pendingRequests = artisans.filter(a => 
    a.status === 'pending' || 
    a.pendingChanges || 
    a.artworks.some(aw => aw.status === 'pending')
  );

  const handleApproveProfile = (artisanId: string) => {
    const newList = artisans.map(a => {
      if (a.id === artisanId) {
        if (a.status === 'pending') return { ...a, status: 'live' as const, rejectionNote: undefined };
        if (a.pendingChanges) {
          const updated = { ...a, ...a.pendingChanges, pendingChanges: undefined, rejectionNote: undefined };
          return updated as Artisan;
        }
      }
      return a;
    });
    onUpdateArtisans(newList);
    setSuccessMsg('Profile changes approved.');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const handleRejectProfile = (artisanId: string) => {
    if (!rejectionReason.trim()) return;

    const newList = artisans.map(a => {
      if (a.id === artisanId) {
        return { 
          ...a, 
          pendingChanges: undefined, 
          rejectionNote: rejectionReason,
          status: a.status === 'pending' ? 'suspended' : a.status // Suspend if it was a new application
        } as Artisan;
      }
      return a;
    });

    onUpdateArtisans(newList);
    setRejectingId(null);
    setRejectionReason('');
    setSuccessMsg('Profile changes rejected with reason.');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const handleApproveArtwork = (artisanId: string, artworkId: string) => {
    const newList = artisans.map(a => {
      if (a.id === artisanId) {
        return {
          ...a,
          artworks: a.artworks.map(aw => aw.id === artworkId ? { ...aw, status: 'live' as const } : aw)
        };
      }
      return a;
    });
    onUpdateArtisans(newList);
    setSuccessMsg('Artwork approved and added to live gallery.');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const handleRejectArtwork = (artisanId: string, artworkId: string) => {
    const newList = artisans.map(a => {
      if (a.id === artisanId) {
        return {
          ...a,
          artworks: a.artworks.map(aw => aw.id === artworkId ? { ...aw, status: 'rejected' as const } : aw)
        };
      }
      return a;
    });
    onUpdateArtisans(newList);
  };

  const handleArtisanSubmitEdits = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const edits = {
      bio: formData.get('bio') as string,
      location: formData.get('location') as string,
    };

    const newList = artisans.map(a => {
      if (a.id === user.artisanId) {
        return { ...a, pendingChanges: edits, rejectionNote: undefined };
      }
      return a;
    });
    onUpdateArtisans(newList);
    setSuccessMsg('Profile updates submitted for admin review.');
    setActiveTab('overview');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const handleAddArtwork = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newAW: Artwork = {
      id: `aw-${Date.now()}`,
      title: formData.get('title') as string,
      description: formData.get('description') as string,
      price: formData.get('price') as string,
      image: 'https://images.unsplash.com/photo-1598300042247-d088f8ab3a91?w=800&fit=crop', // Mock image
      status: 'pending'
    };

    const newList = artisans.map(a => {
      if (a.id === user.artisanId) {
        return { ...a, artworks: [...a.artworks, newAW] };
      }
      return a;
    });
    onUpdateArtisans(newList);
    setSuccessMsg('New artwork submitted for admin review.');
    setActiveTab('overview');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  return (
    <div className="bg-[#cab89d] min-h-screen py-10 px-4 md:px-20 max-w-[1440px] mx-auto">
      {/* Dashboard Header */}
      <div className="flex flex-col md:flex-row justify-between items-end mb-10 border-b border-[#4B3827]/10 pb-8 gap-6">
        <div>
          <h1 className="text-4xl md:text-5xl font-playfair text-[#3E2D1F] mb-2 uppercase tracking-tight">
            {user.role === 'admin' ? 'Archive Registry' : 'Artisan Workspace'}
          </h1>
          <p className="font-lora italic text-[#5A4632]">
            Logged in as <span className="font-bold text-[#4B3827]">{user.name}</span> <span className="text-[10px] bg-[#3E2D1F] text-[#F5F1EA] px-2 py-0.5 ml-2 font-black uppercase tracking-widest">{user.role}</span>
          </p>
        </div>

        <div className="flex gap-2">
           <button 
             onClick={() => setActiveTab('overview')}
             className={`px-6 py-2 text-[10px] font-bold uppercase tracking-[0.2em] border-b-2 transition-all ${activeTab === 'overview' ? 'border-[#7B4A2E] text-[#7B4A2E]' : 'border-transparent text-[#8A7660] hover:text-[#4B3827]'}`}
           >
             Snapshot
           </button>
           {user.role === 'admin' ? (
              <button 
                onClick={() => setActiveTab('review')}
                className={`relative px-6 py-2 text-[10px] font-bold uppercase tracking-[0.2em] border-b-2 transition-all ${activeTab === 'review' ? 'border-[#7B4A2E] text-[#7B4A2E]' : 'border-transparent text-[#8A7660] hover:text-[#4B3827]'}`}
              >
                Review Log
                {pendingRequests.length > 0 && (
                  <span className="absolute -top-1 -right-1 w-4 h-4 bg-[#7B4A2E] text-white text-[9px] flex items-center justify-center rounded-full animate-pulse">
                    {pendingRequests.length}
                  </span>
                )}
              </button>
           ) : (
              <>
                <button 
                  onClick={() => setActiveTab('edit')}
                  className={`relative px-6 py-2 text-[10px] font-bold uppercase tracking-[0.2em] border-b-2 transition-all ${activeTab === 'edit' ? 'border-[#7B4A2E] text-[#7B4A2E]' : 'border-transparent text-[#8A7660] hover:text-[#4B3827]'}`}
                >
                  Edit Profile
                  {(hasPendingProfile || hasRejectedProfile) && (
                    <span className={`absolute -top-1 -right-1 w-2.5 h-2.5 rounded-full border border-[#cab89d] ${hasRejectedProfile ? 'bg-red-600' : 'bg-amber-500 animate-pulse'}`} />
                  )}
                </button>
                <button 
                  onClick={() => setActiveTab('artworks')}
                  className={`relative px-6 py-2 text-[10px] font-bold uppercase tracking-[0.2em] border-b-2 transition-all ${activeTab === 'artworks' ? 'border-[#7B4A2E] text-[#7B4A2E]' : 'border-transparent text-[#8A7660] hover:text-[#4B3827]'}`}
                >
                  Gallery
                  {(pendingArtworksCount > 0 || hasRejectedArtworks) && (
                    <span className={`absolute -top-1 -right-1 flex items-center justify-center min-w-[16px] h-4 rounded-full border border-[#cab89d] px-1 text-[8px] text-white font-black ${hasRejectedArtworks ? 'bg-red-600' : 'bg-amber-500 animate-pulse'}`}>
                      {pendingArtworksCount > 0 ? pendingArtworksCount : '!'}
                    </span>
                  )}
                </button>
              </>
           )}
        </div>
      </div>

      {successMsg && (
        <div className="mb-8 p-4 bg-green-50 border-l-4 border-green-500 text-green-800 text-xs font-bold flex items-center gap-3 animate-fade-in shadow-sm">
           <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg>
           {successMsg}
        </div>
      )}

      {/* --- ADMIN VIEW: REVIEW --- */}
      {user.role === 'admin' && activeTab === 'review' && (
        <section className="space-y-8 animate-fade-in">
           <h2 className="text-2xl font-playfair text-[#3E2D1F] border-l-4 border-[#7B4A2E] pl-4 mb-8">Registry Task Queue</h2>
           {pendingRequests.length > 0 ? (
             <div className="grid grid-cols-1 gap-8">
                {pendingRequests.map(artisan => (
                  <div key={artisan.id} className="bg-[#F2E6D8] p-8 border border-[#D6C7B2] shadow-md flex flex-col gap-6 relative overflow-hidden">
                    <div className="flex flex-col md:flex-row gap-10 items-start">
                      <div className="w-24 h-24 rounded-full overflow-hidden border-2 border-[#D6C7B2] shrink-0">
                        <img src={artisan.image} className="w-full h-full object-cover" alt="" />
                      </div>
                      <div className="flex-grow">
                        <div className="flex items-center gap-4 mb-3">
                          <h3 className="text-2xl font-bold font-playfair text-[#3E2D1F]">{artisan.name}</h3>
                          <span className="text-[9px] bg-[#7B4A2E] text-white px-2 py-0.5 font-black uppercase tracking-[0.2em]">
                            {artisan.pendingChanges ? 'Profile Update' : artisan.status === 'pending' ? 'Verification' : 'Catalog Audit'}
                          </span>
                        </div>
                        <p className="text-sm font-lora italic text-[#5A4632] mb-6">Traditional practitioner of {artisan.role}</p>

                        {(artisan.status === 'pending' || artisan.pendingChanges) && (
                          <div className="mb-8">
                            {artisan.pendingChanges && (
                              <div className="bg-white/40 p-5 border border-[#D6C7B2] mb-6">
                                <p className="text-[10px] font-bold uppercase tracking-widest text-[#8A7660] mb-3">Change Request Details:</p>
                                <ul className="text-xs space-y-3 font-lora">
                                    {Object.entries(artisan.pendingChanges).map(([key, val]) => (
                                      <li key={key} className="flex gap-2">
                                        <span className="font-bold text-[#3E2D1F] capitalize">{key}:</span>
                                        <span className="text-[#5A4632]">{val as string}</span>
                                      </li>
                                    ))}
                                </ul>
                              </div>
                            )}

                            {rejectingId === artisan.id ? (
                               <div className="bg-[#E2D7C6] p-5 border border-[#7B4A2E]/30 animate-fade-in">
                                  <label className="block text-[10px] font-bold uppercase tracking-widest text-[#7B4A2E] mb-2">Reason for Rejection</label>
                                  <textarea 
                                    value={rejectionReason}
                                    onChange={(e) => setRejectionReason(e.target.value)}
                                    placeholder="Please provide guidance for the artisan..."
                                    className="w-full bg-white border border-[#D6C7B2] p-3 text-xs font-lora focus:outline-none focus:ring-1 focus:ring-[#7B4A2E] mb-4"
                                    rows={3}
                                  />
                                  <div className="flex gap-2">
                                    <button 
                                      onClick={() => handleRejectProfile(artisan.id)}
                                      className="bg-[#7B4A2E] text-white px-6 py-2 text-[10px] font-bold uppercase tracking-widest hover:bg-[#3E2D1F] transition-all"
                                    >
                                      Confirm Rejection
                                    </button>
                                    <button 
                                      onClick={() => { setRejectingId(null); setRejectionReason(''); }}
                                      className="text-[10px] font-bold uppercase tracking-widest text-[#3E2D1F] px-4"
                                    >
                                      Cancel
                                    </button>
                                  </div>
                               </div>
                            ) : (
                               <div className="flex gap-3">
                                  <button 
                                    onClick={() => handleApproveProfile(artisan.id)}
                                    className="bg-[#3E2D1F] text-[#F5F1EA] px-8 py-2.5 text-[10px] font-bold uppercase tracking-[0.2em] hover:bg-black transition-all shadow-md"
                                  >
                                    Approve Changes
                                  </button>
                                  <button 
                                    onClick={() => setRejectingId(artisan.id)}
                                    className="border-2 border-[#7B4A2E] text-[#7B4A2E] px-8 py-2 text-[10px] font-bold uppercase tracking-[0.2em] hover:bg-[#7B4A2E] hover:text-white transition-all"
                                  >
                                    Reject Changes
                                  </button>
                               </div>
                            )}
                          </div>
                        )}

                        {artisan.artworks.some(aw => aw.status === 'pending') && (
                          <div className="space-y-5 pt-8 border-t border-[#D6C7B2]/40">
                            <p className="text-[10px] font-bold uppercase tracking-widest text-[#8A7660]">New Catalog Submissions:</p>
                            {artisan.artworks.filter(aw => aw.status === 'pending').map(aw => (
                              <div key={aw.id} className="bg-white/60 p-5 border border-[#D6C7B2] flex gap-6 items-center">
                                <img src={aw.image} className="w-20 h-20 object-cover border border-[#D6C7B2]" alt="" />
                                <div className="flex-grow">
                                  <h4 className="font-playfair font-bold text-lg text-[#3E2D1F]">{aw.title}</h4>
                                  <p className="text-xs font-lora text-[#5A4632]">{aw.price}</p>
                                </div>
                                <div className="flex gap-2">
                                  <button onClick={() => handleApproveArtwork(artisan.id, aw.id)} className="px-5 py-2 bg-green-800 text-white text-[9px] font-bold uppercase tracking-widest hover:bg-green-900">Approve</button>
                                  <button onClick={() => handleRejectArtwork(artisan.id, aw.id)} className="px-5 py-2 border border-[#7B4A2E] text-[#7B4A2E] text-[9px] font-bold uppercase tracking-widest hover:bg-[#7B4A2E] hover:text-white">Reject</button>
                                </div>
                              </div>
                            ))}
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                ))}
             </div>
           ) : (
             <div className="py-24 text-center border-2 border-dashed border-[#D6C7B2] bg-white/10">
                <p className="font-lora italic text-[#8A7660] text-lg">Your review queue is currently empty. The registry is up to date.</p>
             </div>
           )}
        </section>
      )}

      {/* --- ARTISAN VIEW: ARTWORKS --- */}
      {user.role === 'artisan' && activeTab === 'artworks' && myProfile && (
        <section className="animate-fade-in max-w-5xl">
           <div className="flex justify-between items-center mb-10">
              <h2 className="text-3xl font-playfair text-[#3E2D1F] border-l-4 border-[#7B4A2E] pl-4">Digital Catalog</h2>
           </div>

           <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
              <div className="bg-[#F2E6D8] p-8 border border-[#D6C7B2] shadow-lg">
                <h3 className="text-xl font-playfair mb-8 text-[#3E2D1F]">Submit Heritage Work</h3>
                <form onSubmit={handleAddArtwork} className="space-y-6">
                  <div>
                    <label className="block text-[10px] font-bold uppercase tracking-widest text-[#8A7660] mb-2">Title of Artwork</label>
                    <input name="title" required className="w-full bg-white border border-[#D6C7B2] p-3 text-sm font-lora focus:outline-none focus:ring-1 focus:ring-[#7B4A2E]" />
                  </div>
                  <div>
                    <label className="block text-[10px] font-bold uppercase tracking-widest text-[#8A7660] mb-2">Curatorial Description</label>
                    <textarea name="description" required rows={3} className="w-full bg-white border border-[#D6C7B2] p-3 text-sm font-lora focus:outline-none focus:ring-1 focus:ring-[#7B4A2E]" />
                  </div>
                  <div>
                    <label className="block text-[10px] font-bold uppercase tracking-widest text-[#8A7660] mb-2">Estimated Value</label>
                    <input name="price" placeholder="e.g. ₹15,000" required className="w-full bg-white border border-[#D6C7B2] p-3 text-sm font-lora focus:outline-none focus:ring-1 focus:ring-[#7B4A2E]" />
                  </div>
                  <button type="submit" className="w-full bg-[#3E2D1F] text-[#F5F1EA] py-4 text-[10px] font-bold uppercase tracking-[0.2em] hover:bg-black transition-all shadow-md">Submit for Verification</button>
                </form>
              </div>

              <div className="space-y-5">
                <h3 className="text-xl font-playfair mb-6 text-[#3E2D1F]">Gallery Status</h3>
                {myProfile.artworks.length > 0 ? (
                  myProfile.artworks.map(aw => (
                    <div key={aw.id} className="bg-white/80 p-5 border border-[#D6C7B2] flex gap-6 items-center transition-all hover:bg-white relative">
                       <img src={aw.image} className="w-20 h-20 object-cover border border-[#D6C7B2]" alt="" />
                       <div className="flex-grow">
                          <h4 className="font-playfair font-bold text-[#3E2D1F] mb-1">{aw.title}</h4>
                          <span className={`text-[8px] uppercase font-black tracking-[0.2em] px-3 py-1 rounded-full ${
                            aw.status === 'live' ? 'bg-green-100 text-green-800' :
                            aw.status === 'pending' ? 'bg-yellow-100 text-yellow-800' :
                            'bg-red-100 text-red-800'
                          }`}>
                            {aw.status}
                          </span>
                       </div>
                       <p className="text-sm font-bold text-[#7B4A2E] font-lora">{aw.price}</p>
                       {aw.status === 'rejected' && (
                         <div className="absolute top-2 right-2 group cursor-help">
                            <span className="w-4 h-4 rounded-full bg-red-600 text-white flex items-center justify-center text-[10px] font-black">!</span>
                            <div className="absolute right-0 top-6 w-48 bg-[#3E2D1F] text-[#F5F1EA] text-[10px] p-2 rounded-sm shadow-xl opacity-0 group-hover:opacity-100 pointer-events-none transition-opacity z-50">
                               Rejected by curator. Please review guidelines.
                            </div>
                         </div>
                       )}
                    </div>
                  ))
                ) : (
                  <div className="p-10 text-center border-2 border-dashed border-[#D6C7B2] bg-[#F2E6D8]/20">
                    <p className="text-sm font-lora italic text-[#8A7660]">Your digital gallery is empty.</p>
                  </div>
                )}
              </div>
           </div>
        </section>
      )}

      {/* --- OVERVIEW TAB --- */}
      {activeTab === 'overview' && (
        <section className="grid grid-cols-1 lg:grid-cols-3 gap-10 animate-fade-in">
           <div className="lg:col-span-1">
              <div className="bg-[#4B3827] text-[#F5F1EA] p-10 shadow-2xl sticky top-28 border-t-4 border-[#7B4A2E]">
                 <div className="flex items-center gap-6 mb-10">
                    <div className="w-20 h-20 rounded-full bg-[#7B4A2E] flex items-center justify-center text-4xl font-playfair shadow-xl border border-white/10 ring-4 ring-[#4B3827]">
                       {user.name.charAt(0)}
                    </div>
                    <div>
                       <h3 className="text-2xl font-playfair leading-tight text-white">{user.name}</h3>
                       <p className="text-[10px] uppercase tracking-[0.25em] text-[#D6C7B2] font-black">{user.role}</p>
                    </div>
                 </div>

                 <div className="space-y-8">
                    <div>
                       <p className="text-[9px] uppercase tracking-[0.2em] text-[#8A7660] font-black mb-2">Member Since</p>
                       <p className="text-sm font-lora italic text-[#E2D7C6]">2024 Archive Launch</p>
                    </div>
                    <div>
                       <p className="text-[9px] uppercase tracking-[0.2em] text-[#8A7660] font-black mb-2">Registry Tier</p>
                       <p className="text-sm font-lora text-[#E2D7C6]">{user.role === 'admin' ? 'Master Curator' : 'Heritage Practitioner'}</p>
                    </div>
                    {user.role === 'artisan' && myProfile && (
                      <div>
                         <p className="text-[9px] uppercase tracking-[0.2em] text-[#8A7660] font-black mb-2">Public Visibility</p>
                         <p className="text-sm flex items-center gap-3 text-[#E2D7C6]">
                           <span className={`w-2.5 h-2.5 rounded-full ring-2 ring-white/10 ${myProfile.status === 'live' ? 'bg-green-500' : 'bg-yellow-500 animate-pulse'}`}></span>
                           {myProfile.status === 'live' ? 'Live in Archive' : 'Awaiting Review'}
                         </p>
                         {myProfile.rejectionNote && (
                            <div className="mt-6 p-4 bg-red-900/30 border border-red-500/50 rounded-sm">
                               <p className="text-[9px] uppercase font-black tracking-widest text-red-300 mb-1">Feedback from Curators:</p>
                               <p className="text-xs italic text-red-100 font-lora leading-relaxed">"{myProfile.rejectionNote}"</p>
                            </div>
                         )}
                         {myProfile.pendingChanges && (
                           <div className="mt-4 p-3 bg-amber-900/20 border border-amber-500/30 rounded-sm">
                              <p className="text-[9px] uppercase font-black tracking-widest text-amber-300">Update in Progress</p>
                              <p className="text-[10px] text-amber-100 font-lora mt-1 italic">The registry is currently auditing your latest changes.</p>
                           </div>
                         )}
                      </div>
                    )}
                 </div>
              </div>
           </div>

           <div className="lg:col-span-2 space-y-10">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                 <div className="bg-[#F2E6D8] p-8 shadow-md border-b-4 border-[#7B4A2E]">
                    <span className="text-[9px] uppercase font-black tracking-[0.2em] text-[#8A7660]">Masters Catalogued</span>
                    <p className="text-5xl font-playfair mt-3 text-[#3E2D1F]">{artisans.length}</p>
                 </div>
                 <div className="bg-[#F2E6D8] p-8 shadow-md border-b-4 border-[#4B3827]">
                    <span className="text-[9px] uppercase font-black tracking-[0.2em] text-[#8A7660]">Traditions Indexed</span>
                    <p className="text-5xl font-playfair mt-3 text-[#3E2D1F]">{ART_FORMS.length}</p>
                 </div>
                 <div className="bg-[#F2E6D8] p-8 shadow-md border-b-4 border-[#8A7660]">
                    <span className="text-[9px] uppercase font-black tracking-[0.2em] text-[#8A7660]">Moderation Queue</span>
                    <p className="text-5xl font-playfair mt-3 text-[#7B4A2E]">{pendingRequests.length}</p>
                 </div>
              </div>

              <div className="bg-white/40 p-10 border border-[#D6C7B2] rounded-sm">
                 <h3 className="text-2xl font-playfair mb-8 text-[#3E2D1F]">Registry Performance</h3>
                 <div className="space-y-6">
                    <div className="flex justify-between items-center py-4 border-b border-[#4B3827]/10">
                       <span className="text-sm font-lora text-[#5A4632]">Asset Integrity Score</span>
                       <span className="text-[10px] font-black uppercase tracking-widest text-green-700">98.4% Optimal</span>
                    </div>
                    <div className="flex justify-between items-center py-4 border-b border-[#4B3827]/10">
                       <span className="text-sm font-lora text-[#5A4632]">Verification Latency</span>
                       <span className="text-[10px] font-black uppercase tracking-widest text-[#7B4A2E]">~12 Hours</span>
                    </div>
                    <div className="flex justify-between items-center py-4">
                       <span className="text-sm font-lora text-[#5A4632]">Digital Storage Distribution</span>
                       <div className="w-1/3 h-1.5 bg-[#4B3827]/20 rounded-full overflow-hidden">
                          <div className="h-full bg-[#7B4A2E] w-[45%]" />
                       </div>
                    </div>
                 </div>
              </div>
           </div>
        </section>
      )}

      {/* --- EDIT PROFILE VIEW --- */}
      {user.role === 'artisan' && activeTab === 'edit' && myProfile && (
        <section className="animate-fade-in max-w-4xl">
          <div className="flex items-center gap-4 mb-10">
            <h2 className="text-3xl font-playfair text-[#3E2D1F] border-l-4 border-[#7B4A2E] pl-4">Archive Identity Maintenance</h2>
            {hasPendingProfile && (
              <span className="bg-amber-100 text-amber-800 text-[10px] px-3 py-1 font-black uppercase tracking-widest rounded-full animate-pulse border border-amber-200">Pending Review</span>
            )}
          </div>

          {myProfile.rejectionNote && (
            <div className="mb-8 p-6 bg-red-50 border-l-4 border-red-500 shadow-sm animate-fade-in">
               <div className="flex items-center gap-3 mb-2">
                 <span className="w-2 h-2 bg-red-600 rounded-full" />
                 <p className="text-[10px] font-black uppercase tracking-widest text-red-600">Curator Feedback on Previous Attempt:</p>
               </div>
               <p className="text-sm italic text-[#3E2D1F] font-lora">"{myProfile.rejectionNote}"</p>
            </div>
          )}

          <form onSubmit={handleArtisanSubmitEdits} className={`space-y-10 bg-[#F2E6D8] p-10 border border-[#D6C7B2] shadow-xl transition-opacity ${hasPendingProfile ? 'opacity-70 pointer-events-none' : 'opacity-100'}`}>
             <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                <div>
                  <label className="block text-[10px] font-bold uppercase tracking-widest text-[#8A7660] mb-3">Workshop Region</label>
                  <input name="location" defaultValue={myProfile.location} className="w-full bg-white border border-[#D6C7B2] p-3 font-lora text-sm focus:outline-none focus:ring-1 focus:ring-[#7B4A2E]" />
                </div>
                <div>
                   <label className="block text-[10px] font-bold uppercase tracking-widest text-[#8A7660] mb-3">Digital Identity Media</label>
                   <div className="flex items-center gap-4">
                      <div className="w-12 h-12 rounded-sm border border-dashed border-[#8A7660] flex items-center justify-center text-[#8A7660]">
                         <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4"></path></svg>
                      </div>
                      <input type="file" className="text-[10px] text-[#5A4632] uppercase font-bold" />
                   </div>
                </div>
             </div>
             <div>
                <label className="block text-[10px] font-bold uppercase tracking-widest text-[#8A7660] mb-3">Professional Statement / Heritage Bio</label>
                <textarea name="bio" defaultValue={myProfile.bio} rows={6} className="w-full bg-white border border-[#D6C7B2] p-4 font-lora text-sm focus:outline-none focus:ring-1 focus:ring-[#7B4A2E] leading-relaxed" />
             </div>
             <button type="submit" className="bg-[#3E2D1F] text-[#F5F1EA] px-16 py-4 text-[11px] font-black uppercase tracking-[0.3em] hover:bg-black hover:shadow-2xl transition-all shadow-lg active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed">
               {hasPendingProfile ? 'Revision Locked During Audit' : 'Dispatch for Registry Audit'}
             </button>
          </form>
          {hasPendingProfile && (
            <p className="mt-4 text-[10px] text-[#8A7660] italic text-center uppercase tracking-widest font-bold">Your previous submission is still being reviewed by the archive board.</p>
          )}
        </section>
      )}
    </div>
  );
};

export default DashboardPage;

import React, { useState, useMemo } from 'react';
import { User, Artisan, Artwork } from '../types';
import { ART_FORMS } from '../constants';

interface DashboardPageProps {
  user: User;
  artisans: Artisan[];
  onUpdateArtisans: (list: Artisan[]) => void;
}

const DashboardPage: React.FC<DashboardPageProps> = ({ user, artisans, onUpdateArtisans }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'review' | 'edit' | 'artworks'>('overview');
  const [successMsg, setSuccessMsg] = useState('');
  const [rejectingId, setRejectingId] = useState<string | null>(null);
  const [rejectionReason, setRejectionReason] = useState('');

  // Find target artisan if role is artisan
  const myProfile = artisans.find(a => a.id === user.artisanId);

  // Artisan notification logic
  const notifications = useMemo(() => {
    if (!myProfile) return [];
    const logs = [];

    if (myProfile.pendingChanges) {
      logs.push({ type: 'pending', msg: 'Profile revisions are currently under registry audit.', date: 'Just now' });
    }
    if (myProfile.rejectionNote) {
      logs.push({ type: 'rejected', msg: 'Profile update was returned with curator feedback.', date: 'Today' });
    }

    myProfile.artworks.forEach(aw => {
      if (aw.status === 'pending') {
        logs.push({ type: 'pending', msg: `Artwork "${aw.title}" is awaiting verification.`, date: 'Recent' });
      } else if (aw.status === 'rejected') {
        logs.push({ type: 'rejected', msg: `Artwork "${aw.title}" was not approved for the live archive.`, date: 'Recent' });
      } else if (aw.status === 'live') {
        // Mocking an "approved" notification for the log
        logs.push({ type: 'approved', msg: `Artwork "${aw.title}" is now live in the heritage catalog.`, date: 'Recent' });
      }
    });

    return logs.sort((a, b) => (a.type === 'rejected' ? -1 : 1));
  }, [myProfile]);

  const pendingArtworksCount = myProfile?.artworks.filter(aw => aw.status === 'pending').length || 0;
  const hasRejectedArtworks = myProfile?.artworks.some(aw => aw.status === 'rejected') || false;
  const hasPendingProfile = !!myProfile?.pendingChanges;
  const hasRejectedProfile = !!myProfile?.rejectionNote;

  // Pending tasks for admin
  const pendingRequests = artisans.filter(a => 
    a.status === 'pending' || 
    a.pendingChanges || 
    a.artworks.some(aw => aw.status === 'pending')
  );

  const handleApproveProfile = (artisanId: string) => {
    const newList = artisans.map(a => {
      if (a.id === artisanId) {
        if (a.status === 'pending') return { ...a, status: 'live' as const, rejectionNote: undefined };
        if (a.pendingChanges) {
          const updated = { ...a, ...a.pendingChanges, pendingChanges: undefined, rejectionNote: undefined };
          return updated as Artisan;
        }
      }
      return a;
    });
    onUpdateArtisans(newList);
    setSuccessMsg('Profile changes approved.');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const handleRejectProfile = (artisanId: string) => {
    if (!rejectionReason.trim()) return;

    const newList = artisans.map(a => {
      if (a.id === artisanId) {
        return { 
          ...a, 
          pendingChanges: undefined, 
          rejectionNote: rejectionReason,
          status: a.status === 'pending' ? 'suspended' : a.status 
        } as Artisan;
      }
      return a;
    });

    onUpdateArtisans(newList);
    setRejectingId(null);
    setRejectionReason('');
    setSuccessMsg('Profile changes rejected with reason.');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const handleApproveArtwork = (artisanId: string, artworkId: string) => {
    const newList = artisans.map(a => {
      if (a.id === artisanId) {
        return {
          ...a,
          artworks: a.artworks.map(aw => aw.id === artworkId ? { ...aw, status: 'live' as const } : aw)
        };
      }
      return a;
    });
    onUpdateArtisans(newList);
    setSuccessMsg('Artwork approved and added to live gallery.');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const handleRejectArtwork = (artisanId: string, artworkId: string) => {
    const newList = artisans.map(a => {
      if (a.id === artisanId) {
        return {
          ...a,
          artworks: a.artworks.map(aw => aw.id === artworkId ? { ...aw, status: 'rejected' as const } : aw)
        };
      }
      return a;
    });
    onUpdateArtisans(newList);
  };

  const handleArtisanSubmitEdits = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const edits = {
      bio: formData.get('bio') as string,
      location: formData.get('location') as string,
    };

    const newList = artisans.map(a => {
      if (a.id === user.artisanId) {
        return { ...a, pendingChanges: edits, rejectionNote: undefined };
      }
      return a;
    });
    onUpdateArtisans(newList);
    setSuccessMsg('Profile updates submitted for admin review.');
    setActiveTab('overview');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const handleAddArtwork = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newAW: Artwork = {
      id: `aw-${Date.now()}`,
      title: formData.get('title') as string,
      description: formData.get('description') as string,
      price: formData.get('price') as string,
      image: 'https://images.unsplash.com/photo-1598300042247-d088f8ab3a91?w=800&fit=crop', 
      status: 'pending'
    };

    const newList = artisans.map(a => {
      if (a.id === user.artisanId) {
        return { ...a, artworks: [...a.artworks, newAW] };
      }
      return a;
    });
    onUpdateArtisans(newList);
    setSuccessMsg('New artwork submitted for admin review.');
    setActiveTab('overview');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  return (
    <div className="bg-[#cab89d] min-h-screen py-10 px-4 md:px-20 max-w-[1440px] mx-auto">
      {/* Dashboard Header */}
      <div className="flex flex-col md:flex-row justify-between items-end mb-10 border-b border-[#4B3827]/10 pb-8 gap-6">
        <div>
          <h1 className="text-4xl md:text-5xl font-playfair text-[#3E2D1F] mb-2 uppercase tracking-tight">
            {user.role === 'admin' ? 'Archive Registry' : 'Artisan Workspace'}
          </h1>
          <p className="font-lora italic text-[#5A4632]">
            Logged in as <span className="font-bold text-[#4B3827]">{user.name}</span> <span className="text-[10px] bg-[#3E2D1F] text-[#F5F1EA] px-2 py-0.5 ml-2 font-black uppercase tracking-widest">{user.role}</span>
          </p>
        </div>

        <div className="flex gap-2">
           <button 
             onClick={() => setActiveTab('overview')}
             className={`px-6 py-2 text-[10px] font-bold uppercase tracking-[0.2em] border-b-2 transition-all ${activeTab === 'overview' ? 'border-[#7B4A2E] text-[#7B4A2E]' : 'border-transparent text-[#8A7660] hover:text-[#4B3827]'}`}
           >
             Snapshot
           </button>
           {user.role === 'admin' ? (
              <button 
                onClick={() => setActiveTab('review')}
                className={`relative px-6 py-2 text-[10px] font-bold uppercase tracking-[0.2em] border-b-2 transition-all ${activeTab === 'review' ? 'border-[#7B4A2E] text-[#7B4A2E]' : 'border-transparent text-[#8A7660] hover:text-[#4B3827]'}`}
              >
                Review Log
                {pendingRequests.length > 0 && (
                  <span className="absolute -top-1 -right-1 w-4 h-4 bg-[#7B4A2E] text-white text-[9px] flex items-center justify-center rounded-full animate-pulse font-black">
                    {pendingRequests.length}
                  </span>
                )}
              </button>
           ) : (
              <>
                <button 
                  onClick={() => setActiveTab('edit')}
                  className={`relative px-6 py-2 text-[10px] font-bold uppercase tracking-[0.2em] border-b-2 transition-all ${activeTab === 'edit' ? 'border-[#7B4A2E] text-[#7B4A2E]' : 'border-transparent text-[#8A7660] hover:text-[#4B3827]'}`}
                >
                  Edit Profile
                  {(hasPendingProfile || hasRejectedProfile) && (
                    <span className={`absolute -top-1 -right-1 w-3 h-3 rounded-full border border-[#cab89d] flex items-center justify-center text-[8px] text-white font-black ${hasRejectedProfile ? 'bg-red-600 shadow-[0_0_10px_rgba(220,38,38,0.5)]' : 'bg-amber-500 animate-pulse'}`}>
                      {hasRejectedProfile ? '!' : ''}
                    </span>
                  )}
                </button>
                <button 
                  onClick={() => setActiveTab('artworks')}
                  className={`relative px-6 py-2 text-[10px] font-bold uppercase tracking-[0.2em] border-b-2 transition-all ${activeTab === 'artworks' ? 'border-[#7B4A2E] text-[#7B4A2E]' : 'border-transparent text-[#8A7660] hover:text-[#4B3827]'}`}
                >
                  Gallery
                  {(pendingArtworksCount > 0 || hasRejectedArtworks) && (
                    <span className={`absolute -top-1 -right-2 flex items-center justify-center min-w-[18px] h-[18px] rounded-full border border-[#cab89d] px-1 text-[8px] text-white font-black shadow-md ${hasRejectedArtworks ? 'bg-red-600' : 'bg-amber-600 animate-pulse'}`}>
                      {hasRejectedArtworks ? '!' : pendingArtworksCount}
                    </span>
                  )}
                </button>
              </>
           )}
        </div>
      </div>

      {successMsg && (
        <div className="mb-8 p-4 bg-green-50 border-l-4 border-green-500 text-green-800 text-xs font-bold flex items-center gap-3 animate-fade-in shadow-sm">
           <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg>
           {successMsg}
        </div>
      )}

      {/* --- ADMIN VIEW: REVIEW --- */}
      {user.role === 'admin' && activeTab === 'review' && (
        <section className="space-y-8 animate-fade-in">
           <h2 className="text-2xl font-playfair text-[#3E2D1F] border-l-4 border-[#7B4A2E] pl-4 mb-8 uppercase tracking-widest">Registry Task Queue</h2>
           {pendingRequests.length > 0 ? (
             <div className="grid grid-cols-1 gap-8">
                {pendingRequests.map(artisan => (
                  <div key={artisan.id} className="bg-[#F2E6D8] p-8 border border-[#D6C7B2] shadow-md flex flex-col gap-6 relative overflow-hidden group">
                    <div className="flex flex-col md:flex-row gap-10 items-start">
                      <div className="w-24 h-24 rounded-full overflow-hidden border-2 border-[#D6C7B2] shrink-0">
                        <img src={artisan.image} className="w-full h-full object-cover" alt="" />
                      </div>
                      <div className="flex-grow">
                        <div className="flex items-center gap-4 mb-3">
                          <h3 className="text-2xl font-bold font-playfair text-[#3E2D1F]">{artisan.name}</h3>
                          <span className="text-[9px] bg-[#7B4A2E] text-white px-2 py-0.5 font-black uppercase tracking-[0.2em]">
                            {artisan.pendingChanges ? 'Profile Update' : artisan.status === 'pending' ? 'Verification' : 'Catalog Audit'}
                          </span>
                        </div>
                        <p className="text-sm font-lora italic text-[#5A4632] mb-6">Traditional practitioner of {artisan.role}</p>

                        {(artisan.status === 'pending' || artisan.pendingChanges) && (
                          <div className="mb-8">
                            {artisan.pendingChanges && (
                              <div className="bg-white/40 p-5 border border-[#D6C7B2] mb-6 shadow-inner">
                                <p className="text-[10px] font-bold uppercase tracking-widest text-[#8A7660] mb-3">Change Request Details:</p>
                                <ul className="text-xs space-y-3 font-lora">
                                    {Object.entries(artisan.pendingChanges).map(([key, val]) => (
                                      <li key={key} className="flex gap-2">
                                        <span className="font-bold text-[#3E2D1F] capitalize">{key}:</span>
                                        <span className="text-[#5A4632] leading-relaxed">{val as string}</span>
                                      </li>
                                    ))}
                                </ul>
                              </div>
                            )}

                            {rejectingId === artisan.id ? (
                               <div className="bg-[#E2D7C6] p-5 border border-[#7B4A2E]/30 animate-fade-in shadow-xl">
                                  <label className="block text-[10px] font-bold uppercase tracking-widest text-[#7B4A2E] mb-2">Reason for Rejection</label>
                                  <textarea 
                                    value={rejectionReason}
                                    onChange={(e) => setRejectionReason(e.target.value)}
                                    placeholder="Please provide guidance for the artisan..."
                                    className="w-full bg-white border border-[#D6C7B2] p-3 text-xs font-lora focus:outline-none focus:ring-1 focus:ring-[#7B4A2E] mb-4"
                                    rows={3}
                                  />
                                  <div className="flex gap-2">
                                    <button 
                                      onClick={() => handleRejectProfile(artisan.id)}
                                      className="bg-[#7B4A2E] text-white px-6 py-2 text-[10px] font-bold uppercase tracking-widest hover:bg-[#3E2D1F] transition-all"
                                    >
                                      Confirm Rejection
                                    </button>
                                    <button 
                                      onClick={() => { setRejectingId(null); setRejectionReason(''); }}
                                      className="text-[10px] font-bold uppercase tracking-widest text-[#3E2D1F] px-4"
                                    >
                                      Cancel
                                    </button>
                                  </div>
                               </div>
                            ) : (
                               <div className="flex gap-3">
                                  <button 
                                    onClick={() => handleApproveProfile(artisan.id)}
                                    className="bg-[#3E2D1F] text-[#F5F1EA] px-8 py-2.5 text-[10px] font-bold uppercase tracking-[0.2em] hover:bg-black transition-all shadow-md active:scale-95"
                                  >
                                    Approve Changes
                                  </button>
                                  <button 
                                    onClick={() => setRejectingId(artisan.id)}
                                    className="border-2 border-[#7B4A2E] text-[#7B4A2E] px-8 py-2 text-[10px] font-bold uppercase tracking-[0.2em] hover:bg-[#7B4A2E] hover:text-white transition-all active:scale-95"
                                  >
                                    Reject Changes
                                  </button>
                               </div>
                            )}
                          </div>
                        )}

                        {artisan.artworks.some(aw => aw.status === 'pending') && (
                          <div className="space-y-5 pt-8 border-t border-[#D6C7B2]/40">
                            <p className="text-[10px] font-bold uppercase tracking-widest text-[#8A7660]">New Catalog Submissions:</p>
                            {artisan.artworks.filter(aw => aw.status === 'pending').map(aw => (
                              <div key={aw.id} className="bg-white/60 p-5 border border-[#D6C7B2] flex gap-6 items-center hover:bg-white transition-colors">
                                <img src={aw.image} className="w-20 h-20 object-cover border border-[#D6C7B2]" alt="" />
                                <div className="flex-grow">
                                  <h4 className="font-playfair font-bold text-lg text-[#3E2D1F]">{aw.title}</h4>
                                  <p className="text-xs font-lora text-[#5A4632]">{aw.price}</p>
                                </div>
                                <div className="flex gap-2">
                                  <button onClick={() => handleApproveArtwork(artisan.id, aw.id)} className="px-5 py-2 bg-green-800 text-white text-[9px] font-bold uppercase tracking-widest hover:bg-green-900 active:scale-95 transition-all">Approve</button>
                                  <button onClick={() => handleRejectArtwork(artisan.id, aw.id)} className="px-5 py-2 border border-[#7B4A2E] text-[#7B4A2E] text-[9px] font-bold uppercase tracking-widest hover:bg-[#7B4A2E] hover:text-white active:scale-95 transition-all">Reject</button>
                                </div>
                              </div>
                            ))}
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                ))}
             </div>
           ) : (
             <div className="py-24 text-center border-2 border-dashed border-[#D6C7B2] bg-white/10">
                <p className="font-lora italic text-[#8A7660] text-lg">Your review queue is currently empty. The registry is up to date.</p>
             </div>
           )}
        </section>
