                  currentPage === 'dashboard' 
                  ? 'bg-[#3E2D1F] text-white shadow-md' 
                  : 'border border-[#3E2D1F] text-[#3E2D1F] hover:bg-[#3E2D1F] hover:text-white'
                }`}
              >
                <DashboardIcon />
                {user.role} Dashboard
