              <button 
                onClick={onLogout}
                className="flex items-center text-xs font-bold uppercase tracking-widest text-[#7B4A2E] hover:underline transition-colors"
              >
                <LogoutIcon />
                Logout
              </button>
            </div>
          ) : (
            <button 
              onClick={() => handleLinkClick('login')}
              className="flex items-center bg-[#3E2D1F] text-[#F5F1EA] px-6 py-2 text-xs font-bold uppercase tracking-widest hover:bg-black transition-all rounded-sm shadow-md"
