            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          ) : (
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16m-7 6h7" />
            </svg>
          )}
        </button>
      </div>

      {/* Mobile Menu Overlay */}
      {isMenuOpen && (
        <div className="md:hidden bg-[#F2E6D8] border-b border-[#D6C7B2] absolute w-full left-0 p-6 flex flex-col gap-4 shadow-xl animate-fade-in z-50">
          <button onClick={() => handleLinkClick('art-forms')} className="flex items-center text-left text-lg font-playfair text-[#3E2D1F] py-2 border-b border-black/5">
            <ArtFormsIcon />
            Art Forms
          </button>
          <button onClick={() => handleLinkClick('artists')} className="flex items-center text-left text-lg font-playfair text-[#3E2D1F] py-2 border-b border-black/5">
            <ArtistsIcon />
            Artists
          </button>

          {user ? (
             <>
               <button onClick={() => handleLinkClick('dashboard')} className="flex items-center text-left text-sm font-bold uppercase tracking-widest text-[#7B4A2E] py-2">
                 <DashboardIcon />
                 My Dashboard
               </button>
               <button onClick={onLogout} className="flex items-center text-left text-sm font-bold uppercase tracking-widest text-[#4B3827] py-2">
                 <LogoutIcon />
                 Logout
               </button>
             </>
          ) : (
             <button 
               onClick={() => handleLinkClick('login')} 
               className="flex items-center text-left text-sm font-bold uppercase tracking-widest text-[#3E2D1F] py-2"
             >
               <LoginIcon />
               Login
             </button>
          )}
        </div>
      )}
    </header>
  );
